--
-- Name: action_decisions_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.action_decisions_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- App roles must use the governed SECURITY DEFINER RPCs. Grants are the first boundary; this is
  -- the second line of defence against a future blanket GRANT. Compare with the table owner rather
  -- than a hard-coded role name so local and hosted Supabase ownership can differ safely. The commit
  -- and paired-review RPCs run as that same migration owner; direct PostgREST DML does not.
  IF current_user IS DISTINCT FROM (
    SELECT pg_catalog.pg_get_userbyid(c.relowner)
      FROM pg_catalog.pg_class c WHERE c.oid = TG_RELID
  ) THEN
    RAISE EXCEPTION 'action_decisions writes must use the governed RPCs';
  END IF;

  -- DELETE erases the audit record rather than transitioning it. The owner may clean isolated local
  -- fixtures and execute an explicit migration; no application role can reach this branch.
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  -- INSERT: a decision is BORN unapproved. Previously the guard was BEFORE UPDATE only, so a row
  -- could be inserted straight into approval_state='approved' with a caller-chosen approved_at —
  -- reproduced with an approved_at of 1999-01-01. Approval is a governed transition, never an
  -- initial value, and approved_at is stamped internally or not at all.
  IF TG_OP = 'INSERT' THEN
    IF NEW.approval_state IS DISTINCT FROM 'not_requested' THEN
      RAISE EXCEPTION 'action_decisions rows must be created with approval_state = ''not_requested''; approval is a governed change-request transition, not an insert value';
    END IF;
    IF NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'approved_at is stamped internally by the approval transition and may not be supplied by the caller';
    END IF;
    RETURN NEW;
  END IF;

  -- Every decision fact is frozen. Listed explicitly rather than via a blanket comparison so that a
  -- column added later must be classified deliberately.
  -- Identity and creation time are frozen too: an audit record whose id or created_at can move is
  -- not an audit record.
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'action_decisions.id and created_at are immutable';
  END IF;

  -- approved_at may change ONLY as part of a governed approval transition (handled below).
  IF NEW.approved_at IS DISTINCT FROM OLD.approved_at
     AND NEW.approval_state IS NOT DISTINCT FROM OLD.approval_state THEN
    RAISE EXCEPTION 'approved_at cannot be set directly; it is stamped by the approval transition';
  END IF;

  IF (NEW.ad_account_id, NEW.action_kind, NEW.target_level, NEW.target_id,
      NEW.evidence_plane, NEW.evidence_basis, NEW.authority_tier, NEW.authority_reason, NEW.owner_copy,
      NEW.direction_ceiling, NEW.direction_reason,
      NEW.policy_version, NEW.evaluated_at, NEW.window_start, NEW.window_end,
      NEW.objective, NEW.matured, NEW.continuity, NEW.windows_conflict,
      NEW.metrics, NEW.proposed_mutation, NEW.source_kind, NEW.source_id, NEW.dedupe_key)
     IS DISTINCT FROM
     (OLD.ad_account_id, OLD.action_kind, OLD.target_level, OLD.target_id,
      OLD.evidence_plane, OLD.evidence_basis, OLD.authority_tier, OLD.authority_reason, OLD.owner_copy,
      OLD.direction_ceiling, OLD.direction_reason,
      OLD.policy_version, OLD.evaluated_at, OLD.window_start, OLD.window_end,
      OLD.objective, OLD.matured, OLD.continuity, OLD.windows_conflict,
      OLD.metrics, OLD.proposed_mutation, OLD.source_kind, OLD.source_id, OLD.dedupe_key)
  THEN
    RAISE EXCEPTION 'action_decisions rows are immutable except for governed approval transitions; re-evaluate by INSERTing a new decision';
  END IF;

  -- Approval may move only along governed edges.
  IF NEW.approval_state IS DISTINCT FROM OLD.approval_state THEN
    IF NOT (
      (OLD.approval_state = 'not_requested' AND NEW.approval_state = 'pending')
      OR (OLD.approval_state = 'pending' AND NEW.approval_state IN ('approved','rejected'))
    ) THEN
      RAISE EXCEPTION 'illegal approval transition % -> %', OLD.approval_state, NEW.approval_state;
    END IF;
    -- Only an execution-eligible decision can be approved on the engine's authority: approving
    -- something the evidence never authorised would launder a diagnostic into an executable
    -- instruction. ADR-059: an owner_review decision may be approved only through a change request the
    -- OWNER initiated; diagnostic_only never.
    IF NEW.approval_state = 'approved' AND OLD.authority_tier <> 'execution_eligible'
       AND NOT (OLD.authority_tier = 'owner_review' AND EXISTS (
         SELECT 1 FROM public.change_requests cr
          WHERE cr.action_decision_id = OLD.id AND cr.initiated_by = 'owner' AND cr.rollback_of IS NULL)) THEN
      RAISE EXCEPTION 'cannot approve a decision whose authority tier is % (only execution_eligible may be approved)', OLD.authority_tier;
    END IF;
    -- The caller never controls the timestamp. Even a privileged direct UPDATE that supplies its own
    -- value is overwritten; lower roles cannot reach the table directly at all.
    IF NEW.approval_state = 'approved' THEN NEW.approved_at := now(); END IF;
    IF NEW.approval_state = 'rejected' THEN NEW.approved_at := NULL; END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: FUNCTION action_decisions_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.action_decisions_guard() IS 'Governed audit guard: blocks every application-role DML operation even if table grants drift, freezes every decision fact after insert, and permits only owner-context approval transitions (not_requested -> pending -> approved|rejected), with approval restricted to execution_eligible rows, or owner_review rows referenced by an owner-initiated change request (ADR-059). Re-evaluation means a NEW row.';


--
-- Name: ad_creative_assignment_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ad_creative_assignment_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_capture_owner pg_catalog.name;
  v_ledger_owner pg_catalog.name;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT
      pg_catalog.pg_get_userbyid(p.proowner),
      pg_catalog.pg_get_userbyid(c.relowner)
    INTO STRICT v_capture_owner, v_ledger_owner
    FROM pg_catalog.pg_proc p
    CROSS JOIN pg_catalog.pg_class c
    WHERE p.oid =
      'public.capture_ad_creative_assignment_observation()'::pg_catalog.regprocedure
      AND c.oid =
        'public.ad_creative_assignment_observations'::pg_catalog.regclass;

    IF pg_catalog.pg_trigger_depth() = 2
      AND v_capture_owner = v_ledger_owner
      AND current_user = v_capture_owner THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'direct creative assignment inserts are forbidden; use ads capture';
  END IF;
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'creative assignment ledger is append-only; truncate is forbidden';
  END IF;
  RAISE EXCEPTION 'creative assignment observations are immutable and append-only';
END;
$$;


