--
-- Name: action_decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.action_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    action_kind text NOT NULL,
    target_level text NOT NULL,
    target_id text,
    evidence_plane text NOT NULL,
    evidence_basis text NOT NULL,
    authority_tier text NOT NULL,
    authority_reason text NOT NULL,
    owner_copy text NOT NULL,
    direction_supported boolean GENERATED ALWAYS AS ((direction_ceiling <> 'unsupported'::text)) STORED,
    direction_ceiling text NOT NULL,
    direction_reason text NOT NULL,
    policy_version integer NOT NULL,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    window_start date,
    window_end date,
    objective text,
    matured boolean,
    continuity boolean,
    windows_conflict boolean,
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    proposed_mutation jsonb,
    source_kind text NOT NULL,
    source_id text,
    approval_state text DEFAULT 'not_requested'::text NOT NULL,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    dedupe_key text NOT NULL,
    paid_cohort_recent_generation_id uuid,
    paid_cohort_matured_generation_id uuid,
    causal_contribution_estimate_id uuid,
    pragmatic_media_buyer boolean DEFAULT false NOT NULL,
    CONSTRAINT action_decisions_approval_domain CHECK ((approval_state = ANY (ARRAY['not_requested'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT action_decisions_basis_domain CHECK ((evidence_basis = ANY (ARRAY['interaction_cohort_complete'::text, 'meta_modelled_association'::text, 'calendar_period_signal'::text, 'unavailable'::text, 'decision_grade_causal_estimate'::text]))),
    CONSTRAINT action_decisions_ceiling_domain CHECK ((direction_ceiling = ANY (ARRAY['unsupported'::text, 'owner_review'::text, 'execution'::text]))),
    CONSTRAINT action_decisions_dedupe_nonblank CHECK ((length(btrim(dedupe_key)) > 0)),
    CONSTRAINT action_decisions_execution_requires_cohort CHECK (((authority_tier <> 'execution_eligible'::text) OR (direction_supported AND (((policy_version < 4) AND (evidence_basis = 'interaction_cohort_complete'::text) AND (evidence_plane = 'interaction_cohort'::text)) OR ((policy_version >= 4) AND (evidence_basis = 'decision_grade_causal_estimate'::text) AND (evidence_plane = 'causal_contribution'::text) AND (causal_contribution_estimate_id IS NOT NULL)))))),
    CONSTRAINT action_decisions_kind_domain CHECK ((action_kind = ANY (ARRAY['budget_scale'::text, 'budget_cut'::text, 'pause'::text, 'activate'::text, 'creative_refresh'::text, 'structural'::text, 'observe'::text]))),
    CONSTRAINT action_decisions_level_domain CHECK ((target_level = ANY (ARRAY['account'::text, 'campaign'::text, 'adset'::text, 'ad'::text, 'audience'::text, 'creative'::text]))),
    CONSTRAINT action_decisions_paid_cohort_lineage_shape CHECK ((((policy_version < 2) AND (paid_cohort_recent_generation_id IS NULL) AND (paid_cohort_matured_generation_id IS NULL)) OR ((policy_version >= 2) AND (((evidence_basis = 'interaction_cohort_complete'::text) AND (evidence_plane = 'interaction_cohort'::text) AND (action_kind = ANY (ARRAY['budget_scale'::text, 'budget_cut'::text, 'pause'::text, 'activate'::text])) AND (paid_cohort_recent_generation_id IS NOT NULL) AND (paid_cohort_matured_generation_id IS NOT NULL)) OR ((evidence_basis <> 'interaction_cohort_complete'::text) AND (evidence_plane <> 'interaction_cohort'::text) AND (paid_cohort_recent_generation_id IS NULL) AND (paid_cohort_matured_generation_id IS NULL)))))),
    CONSTRAINT action_decisions_plane_domain CHECK ((evidence_plane = ANY (ARRAY['interaction_cohort'::text, 'exact_paid_join'::text, 'ledger_business'::text, 'meta_modelled'::text, 'ga_telemetry'::text, 'structural'::text, 'causal_contribution'::text]))),
    CONSTRAINT action_decisions_policy_version_positive CHECK ((policy_version >= 1)),
    CONSTRAINT action_decisions_source_domain CHECK ((source_kind = ANY (ARRAY['flag'::text, 'recommendation'::text, 'alert'::text, 'diagnostic'::text, 'evaluator'::text, 'report'::text, 'creative_fatigue'::text, 'legacy'::text]))),
    CONSTRAINT action_decisions_target_identity CHECK ((((target_level = 'account'::text) AND (target_id IS NULL)) OR ((target_level <> 'account'::text) AND (target_id IS NOT NULL) AND (length(btrim(target_id)) > 0)))),
    CONSTRAINT action_decisions_tier_domain CHECK ((authority_tier = ANY (ARRAY['execution_eligible'::text, 'owner_review'::text, 'diagnostic_only'::text]))),
    CONSTRAINT action_decisions_tier_within_ceiling CHECK (
CASE direction_ceiling
    WHEN 'unsupported'::text THEN (authority_tier = 'diagnostic_only'::text)
    WHEN 'owner_review'::text THEN (authority_tier = ANY (ARRAY['diagnostic_only'::text, 'owner_review'::text]))
    ELSE true
END),
    CONSTRAINT action_decisions_v3_commercial_objective CHECK (((policy_version < 3) OR (objective = 'maximize_incremental_contribution_from_ad_attributed_collected_revenue'::text))),
    CONSTRAINT action_decisions_v4_money_quarantine CHECK (((policy_version < 4) OR (((action_kind = ANY (ARRAY['budget_scale'::text, 'budget_cut'::text, 'pause'::text, 'activate'::text])) AND (((causal_contribution_estimate_id IS NULL) AND (authority_tier = 'diagnostic_only'::text) AND (direction_ceiling = 'unsupported'::text) AND (pragmatic_media_buyer IS NOT TRUE)) OR ((causal_contribution_estimate_id IS NULL) AND (pragmatic_media_buyer IS TRUE) AND (authority_tier = 'owner_review'::text) AND (direction_ceiling = 'owner_review'::text) AND (evidence_plane = 'interaction_cohort'::text) AND (evidence_basis = 'interaction_cohort_complete'::text)) OR ((causal_contribution_estimate_id IS NULL) AND (pragmatic_media_buyer IS TRUE) AND (authority_tier = 'owner_review'::text) AND (direction_ceiling = 'owner_review'::text) AND (evidence_plane = 'meta_modelled'::text) AND (evidence_basis = 'meta_modelled_association'::text)) OR ((causal_contribution_estimate_id IS NOT NULL) AND (evidence_plane = 'causal_contribution'::text) AND (evidence_basis = 'decision_grade_causal_estimate'::text)))) OR ((action_kind <> ALL (ARRAY['budget_scale'::text, 'budget_cut'::text, 'pause'::text, 'activate'::text])) AND (causal_contribution_estimate_id IS NULL))))),
    CONSTRAINT action_decisions_window_order CHECK (((window_start IS NULL) OR (window_end IS NULL) OR (window_start <= window_end)))
);


--
-- Name: TABLE action_decisions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.action_decisions IS 'The ONE durable authority decision about a proposed action. Owner-facing surfaces read this (or a deterministic projection of it) instead of parsing rendered English. policy_version is the structural legacy cutover: rows below the current floor are diagnostic_only regardless of wording. Never a second recommendation store — source_kind/source_id point at the producing artifact.';


--
-- Name: COLUMN action_decisions.owner_copy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.owner_copy IS 'The sole owner-facing action projection emitted by the policy version that created this row. Source-artifact prose is not authority.';


--
-- Name: COLUMN action_decisions.direction_ceiling; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.direction_ceiling IS 'How far the EVIDENCE could carry this action: unsupported | owner_review | execution. A 2x zero-outcome window is owner_review; 3x is execution (high-urgency stop). NOTE: the database enforces that authority_tier stays within this ceiling and that execution requires interaction-cohort evidence — it does NOT re-derive the economics. The CPA/threshold arithmetic lives in src/lib/authority/directional-policy.ts; this column records its verdict, it does not validate it.';


--
-- Name: COLUMN action_decisions.objective; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.objective IS 'Policy-v3 governed commercial objective. Meta campaign delivery objectives are diagnostic context and must not be stored as the north star.';


--
-- Name: COLUMN action_decisions.continuity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.continuity IS 'Whether the setup responsible for the evaluated spend was proven unchanged. NULL = unknown, which blocks money authority — unknown is never treated as unchanged.';


--
-- Name: COLUMN action_decisions.metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.metrics IS 'Numeric evidence snapshot only (spend, outcomes, CPA, targets). NEVER customer data — no names, emails, phone numbers or outcome identities.';


--
-- Name: COLUMN action_decisions.dedupe_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.dedupe_key IS 'Idempotency key: source artifact + target + window + policy generation. UNIQUE per account, so a retried or duplicated pipeline run updates one row instead of minting a second decision.';


--
-- Name: COLUMN action_decisions.paid_cohort_recent_generation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.paid_cohort_recent_generation_id IS 'Policy-v2 immutable lineage to the recent_scale generation used for scale economics and recent corroboration.';


--
-- Name: COLUMN action_decisions.paid_cohort_matured_generation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.paid_cohort_matured_generation_id IS 'Policy-v2 immutable lineage to the same-run matured_cut generation. Cut/pause additionally require its exact target unit to be complete.';


--
-- Name: COLUMN action_decisions.causal_contribution_estimate_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.causal_contribution_estimate_id IS 'Policy-v4 exact lineage to the causal contribution estimate for this experiment target and action estimand. Current estimates grant none authority.';


--
-- Name: COLUMN action_decisions.pragmatic_media_buyer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.action_decisions.pragmatic_media_buyer IS 'When true, this owner-reviewed money action rests on labeled non-causal evidence: either
   attributed paid-cohort association (evidence_basis=interaction_cohort_complete) or Meta-modelled
   attribution (evidence_basis=meta_modelled_association). Execution still requires owner approval;
   automatic execution still requires a causal estimate.';


--
-- Name: approve_action_decision(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_action_decision(p_id uuid, p_approve boolean DEFAULT true) RETURNS public.action_decisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_row public.action_decisions;
BEGIN
  UPDATE public.action_decisions
     SET approval_state = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END
   WHERE id = p_id
  RETURNING * INTO v_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'action_decision % not found', p_id; END IF;
  RETURN v_row;   -- the guard trigger enforces the legal edge and the execution_eligible rule
END $$;


--
-- Name: business_context_approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_context_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    artifact_id uuid NOT NULL,
    artifact_hash text NOT NULL,
    decision text NOT NULL,
    revision integer NOT NULL,
    previous_approval_id uuid,
    reviewed_by text NOT NULL,
    reason text NOT NULL,
    review_due_at timestamp with time zone,
    dedupe_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_context_approval_actor_nonblank CHECK ((length(btrim(reviewed_by)) > 0)),
    CONSTRAINT business_context_approval_decision CHECK ((decision = ANY (ARRAY['approved'::text, 'withdrawn'::text]))),
    CONSTRAINT business_context_approval_dedupe_nonblank CHECK ((length(btrim(dedupe_key)) > 0)),
    CONSTRAINT business_context_approval_due_contract CHECK ((((decision = 'approved'::text) AND (review_due_at IS NOT NULL)) OR ((decision = 'withdrawn'::text) AND (review_due_at IS NULL)))),
    CONSTRAINT business_context_approval_hash_format CHECK ((artifact_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT business_context_approval_reason_nonblank CHECK ((length(btrim(reason)) > 0)),
    CONSTRAINT business_context_approval_revision_positive CHECK ((revision > 0))
);


--
-- Name: TABLE business_context_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.business_context_approvals IS 'Append-only owner decisions over exact business-context artifacts and hashes. review_due_at is owner supplied; Maxx has no implicit age default.';


--
-- Name: approve_business_context_version(uuid, uuid, text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_business_context_version(p_ad_account_id uuid, p_artifact_id uuid, p_expected_hash text, p_expected_previous_approval_id uuid, p_reviewed_by text, p_reason text, p_review_due_at timestamp with time zone, p_dedupe_key text) RETURNS public.business_context_approvals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_existing public.business_context_approvals;
  v_previous public.business_context_approvals;
  v_artifact public.business_context_versions;
  v_latest_artifact public.business_context_versions;
  v_row public.business_context_approvals;
  v_expected jsonb;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_ad_account_id::text || ':governed-planning-context', 0));
  LOCK TABLE public.ad_accounts IN SHARE MODE;
  IF NOT (
    SELECT pg_catalog.count(*) = 1
       AND pg_catalog.count(*) FILTER (WHERE id=p_ad_account_id) = 1
      FROM public.ad_accounts WHERE is_active IS TRUE
  ) THEN RAISE EXCEPTION 'governed context requires the sole active ad account'; END IF;
  v_expected := pg_catalog.jsonb_build_object(
    'ad_account_id',p_ad_account_id,'artifact_id',p_artifact_id,'artifact_hash',p_expected_hash,
    'decision','approved','previous_approval_id',p_expected_previous_approval_id,
    'reviewed_by',p_reviewed_by,'reason',p_reason,'review_due_at',p_review_due_at,
    'dedupe_key',p_dedupe_key);

  SELECT * INTO v_existing FROM public.business_context_approvals
   WHERE ad_account_id=p_ad_account_id AND dedupe_key=p_dedupe_key;
  IF FOUND THEN
    IF (pg_catalog.to_jsonb(v_existing) - ARRAY['id','revision','created_at'])
       IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION 'business context approval dedupe collision for key %', p_dedupe_key;
    END IF;
    RETURN v_existing;
  END IF;

  IF p_review_due_at IS NULL OR p_review_due_at <= pg_catalog.transaction_timestamp() THEN
    RAISE EXCEPTION 'business context approval requires a future review deadline';
  END IF;
  IF length(pg_catalog.btrim(COALESCE(p_reviewed_by,''))) = 0
     OR length(pg_catalog.btrim(COALESCE(p_reason,''))) = 0 THEN
    RAISE EXCEPTION 'business context approval requires actor and reason';
  END IF;

  SELECT * INTO v_previous FROM public.business_context_approvals
   WHERE ad_account_id=p_ad_account_id ORDER BY revision DESC LIMIT 1;
  IF (CASE WHEN FOUND THEN v_previous.id ELSE NULL END)
     IS DISTINCT FROM p_expected_previous_approval_id THEN
    RAISE EXCEPTION 'business context stale head: expected %, current %',
      p_expected_previous_approval_id, v_previous.id;
  END IF;

  SELECT * INTO v_artifact FROM public.business_context_versions
   WHERE id=p_artifact_id AND ad_account_id=p_ad_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'business context artifact not found or account mismatch'; END IF;
  IF v_artifact.content_hash IS DISTINCT FROM p_expected_hash THEN
    RAISE EXCEPTION 'business context hash mismatch';
  END IF;
  SELECT * INTO v_latest_artifact FROM public.business_context_versions
   WHERE ad_account_id=p_ad_account_id ORDER BY revision DESC LIMIT 1;
  IF v_latest_artifact.content_hash IS DISTINCT FROM v_artifact.content_hash THEN
    RAISE EXCEPTION 'newer business observation awaits owner review';
  END IF;

  INSERT INTO public.business_context_approvals(
    ad_account_id,artifact_id,artifact_hash,decision,revision,previous_approval_id,
    reviewed_by,reason,review_due_at,dedupe_key)
  VALUES (
    p_ad_account_id,p_artifact_id,p_expected_hash,'approved',COALESCE(v_previous.revision,0)+1,
    p_expected_previous_approval_id,p_reviewed_by,p_reason,p_review_due_at,p_dedupe_key)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: causal_measurement_design_approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.causal_measurement_design_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    experiment_id uuid NOT NULL,
    artifact_id uuid NOT NULL,
    artifact_hash text NOT NULL,
    decision text NOT NULL,
    revision integer NOT NULL,
    previous_approval_id uuid,
    reviewed_by text NOT NULL,
    reason text NOT NULL,
    dedupe_key text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT causal_design_approval_actor CHECK (((length(btrim(reviewed_by)) >= 1) AND (length(btrim(reviewed_by)) <= 256))),
    CONSTRAINT causal_design_approval_decision CHECK ((decision = ANY (ARRAY['approved'::text, 'withdrawn'::text]))),
    CONSTRAINT causal_design_approval_dedupe CHECK (((length(btrim(dedupe_key)) >= 1) AND (length(btrim(dedupe_key)) <= 512))),
    CONSTRAINT causal_design_approval_hash CHECK ((artifact_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT causal_design_approval_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2048))),
    CONSTRAINT causal_design_approval_revision CHECK ((revision > 0))
);


--
-- Name: TABLE causal_measurement_design_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.causal_measurement_design_approvals IS 'Append-only owner review of exact causal design artifacts. Approval must occur before the measurement window and creates no action authority.';


--
-- Name: approve_causal_measurement_design(uuid, uuid, uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_causal_measurement_design(p_ad_account_id uuid, p_experiment_id uuid, p_artifact_id uuid, p_expected_hash text, p_expected_previous_approval_id uuid, p_reviewed_by text, p_reason text, p_dedupe_key text) RETURNS public.causal_measurement_design_approvals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_existing public.causal_measurement_design_approvals;
  v_previous public.causal_measurement_design_approvals;
  v_artifact public.causal_measurement_design_versions;
  v_latest public.causal_measurement_design_versions;
  v_row public.causal_measurement_design_approvals;
  v_expected jsonb;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    p_ad_account_id::text || ':causal-design:' || p_experiment_id::text,0));
  LOCK TABLE public.ad_accounts IN SHARE MODE;
  IF NOT (
    SELECT pg_catalog.count(*)=1
      AND pg_catalog.count(*) FILTER (WHERE id=p_ad_account_id)=1
      FROM public.ad_accounts WHERE is_active IS TRUE
  ) THEN RAISE EXCEPTION 'causal measurement design requires the sole active ad account'; END IF;
  v_expected := pg_catalog.jsonb_build_object(
    'ad_account_id',p_ad_account_id,'experiment_id',p_experiment_id,
    'artifact_id',p_artifact_id,'artifact_hash',p_expected_hash,'decision','approved',
    'previous_approval_id',p_expected_previous_approval_id,'reviewed_by',p_reviewed_by,
    'reason',p_reason,'dedupe_key',p_dedupe_key);
  SELECT * INTO v_existing FROM public.causal_measurement_design_approvals
   WHERE ad_account_id=p_ad_account_id AND dedupe_key=p_dedupe_key;
  IF FOUND THEN
    IF (pg_catalog.to_jsonb(v_existing)-ARRAY['id','revision','created_at']) IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION 'causal measurement design approval dedupe collision';
    END IF;
    RETURN v_existing;
  END IF;
  SELECT * INTO v_previous FROM public.causal_measurement_design_approvals
   WHERE ad_account_id=p_ad_account_id AND experiment_id=p_experiment_id
   ORDER BY revision DESC LIMIT 1;
  IF (CASE WHEN FOUND THEN v_previous.id ELSE NULL END)
     IS DISTINCT FROM p_expected_previous_approval_id THEN
    RAISE EXCEPTION 'causal measurement design approval stale head';
  END IF;
  SELECT * INTO v_artifact FROM public.causal_measurement_design_versions
   WHERE ad_account_id=p_ad_account_id AND experiment_id=p_experiment_id AND id=p_artifact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'causal measurement design artifact not found'; END IF;
  IF v_artifact.content_hash IS DISTINCT FROM p_expected_hash THEN
    RAISE EXCEPTION 'causal measurement design hash mismatch';
  END IF;
  SELECT * INTO v_latest FROM public.causal_measurement_design_versions
   WHERE ad_account_id=p_ad_account_id AND experiment_id=p_experiment_id
   ORDER BY revision DESC LIMIT 1;
  IF v_latest.id IS DISTINCT FROM v_artifact.id THEN
    RAISE EXCEPTION 'newer causal measurement design awaits owner review';
  END IF;
  IF v_artifact.captured_at>pg_catalog.transaction_timestamp() THEN
    RAISE EXCEPTION 'causal measurement design capture time has not happened yet';
  END IF;
  IF pg_catalog.transaction_timestamp()>=v_artifact.measurement_start THEN
    RAISE EXCEPTION 'causal measurement design approval must happen before measurement starts';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.experiments
     WHERE id=p_experiment_id AND ad_account_id=p_ad_account_id
       AND status IN ('draft','proposed') AND started_at IS NULL
       AND primary_metric='causal_incremental_contribution'
  ) THEN RAISE EXCEPTION 'causal measurement experiment already started or is not eligible'; END IF;
  IF length(pg_catalog.btrim(COALESCE(p_reviewed_by,'')))=0
     OR length(pg_catalog.btrim(COALESCE(p_reason,'')))=0 THEN
    RAISE EXCEPTION 'causal measurement design approval requires actor and reason';
  END IF;
  INSERT INTO public.causal_measurement_design_approvals(
    ad_account_id,experiment_id,artifact_id,artifact_hash,decision,revision,
    previous_approval_id,reviewed_by,reason,dedupe_key)
  VALUES (
    p_ad_account_id,p_experiment_id,p_artifact_id,p_expected_hash,'approved',
    COALESCE(v_previous.revision,0)+1,p_expected_previous_approval_id,p_reviewed_by,p_reason,p_dedupe_key)
  RETURNING * INTO v_row;
  UPDATE public.experiments SET status='proposed'
   WHERE id=p_experiment_id AND ad_account_id=p_ad_account_id AND status='draft';
  RETURN v_row;
END
$$;


--
-- Name: economics_policy_approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.economics_policy_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    artifact_id uuid NOT NULL,
    artifact_hash text NOT NULL,
    decision text NOT NULL,
    revision integer NOT NULL,
    previous_approval_id uuid,
    effective_from timestamp with time zone,
    reviewed_by text NOT NULL,
    reason text NOT NULL,
    review_due_at timestamp with time zone,
    dedupe_key text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT economics_policy_approval_actor CHECK (((length(btrim(reviewed_by)) >= 1) AND (length(btrim(reviewed_by)) <= 256))),
    CONSTRAINT economics_policy_approval_decision CHECK ((decision = ANY (ARRAY['approved'::text, 'withdrawn'::text]))),
    CONSTRAINT economics_policy_approval_dedupe CHECK (((length(btrim(dedupe_key)) >= 1) AND (length(btrim(dedupe_key)) <= 512))),
    CONSTRAINT economics_policy_approval_hash CHECK ((artifact_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT economics_policy_approval_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2048))),
    CONSTRAINT economics_policy_approval_revision CHECK ((revision > 0)),
    CONSTRAINT economics_policy_approval_time_contract CHECK ((((decision = 'approved'::text) AND (effective_from IS NOT NULL) AND (review_due_at IS NOT NULL) AND isfinite(effective_from) AND isfinite(review_due_at) AND (review_due_at > effective_from)) OR ((decision = 'withdrawn'::text) AND (effective_from IS NULL) AND (review_due_at IS NULL))))
);


--
-- Name: TABLE economics_policy_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.economics_policy_approvals IS 'Append-only owner decisions over exact economics policy artifacts. Existence of a policy is not approval and creates no contribution or action authority.';


--
-- Name: approve_economics_policy_version(uuid, uuid, text, uuid, timestamp with time zone, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_economics_policy_version(p_ad_account_id uuid, p_artifact_id uuid, p_expected_hash text, p_expected_previous_approval_id uuid, p_effective_from timestamp with time zone, p_reviewed_by text, p_reason text, p_review_due_at timestamp with time zone, p_dedupe_key text) RETURNS public.economics_policy_approvals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_existing public.economics_policy_approvals;
  v_previous public.economics_policy_approvals;
  v_prior_approved public.economics_policy_approvals;
  v_artifact public.economics_policy_versions;
  v_latest_artifact public.economics_policy_versions;
  v_row public.economics_policy_approvals;
  v_expected jsonb;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    p_ad_account_id::text || ':governed-economics-policy',0));
  LOCK TABLE public.ad_accounts IN SHARE MODE;
  IF NOT (
    SELECT pg_catalog.count(*)=1
      AND pg_catalog.count(*) FILTER (WHERE id=p_ad_account_id)=1
      FROM public.ad_accounts WHERE is_active IS TRUE
  ) THEN RAISE EXCEPTION 'economics policy requires the sole active ad account'; END IF;

  v_expected := pg_catalog.jsonb_build_object(
    'ad_account_id',p_ad_account_id,'artifact_id',p_artifact_id,
    'artifact_hash',p_expected_hash,'decision','approved',
    'previous_approval_id',p_expected_previous_approval_id,'effective_from',p_effective_from,
    'reviewed_by',p_reviewed_by,'reason',p_reason,'review_due_at',p_review_due_at,
    'dedupe_key',p_dedupe_key);
  SELECT * INTO v_existing FROM public.economics_policy_approvals
   WHERE ad_account_id=p_ad_account_id AND dedupe_key=p_dedupe_key;
  IF FOUND THEN
    IF (pg_catalog.to_jsonb(v_existing)-ARRAY['id','revision','created_at']) IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION 'economics policy approval dedupe collision';
    END IF;
    RETURN v_existing;
  END IF;
  IF p_review_due_at IS NULL OR p_review_due_at<=pg_catalog.transaction_timestamp()
     OR p_effective_from IS NULL OR p_review_due_at<=p_effective_from THEN
    RAISE EXCEPTION 'economics policy approval requires an effective time and future review deadline';
  END IF;
  IF length(pg_catalog.btrim(COALESCE(p_reviewed_by,'')))=0
     OR length(pg_catalog.btrim(COALESCE(p_reason,'')))=0 THEN
    RAISE EXCEPTION 'economics policy approval requires actor and reason';
  END IF;
  SELECT * INTO v_previous FROM public.economics_policy_approvals
   WHERE ad_account_id=p_ad_account_id ORDER BY revision DESC LIMIT 1;
  IF (CASE WHEN FOUND THEN v_previous.id ELSE NULL END)
     IS DISTINCT FROM p_expected_previous_approval_id THEN
    RAISE EXCEPTION 'economics policy stale head';
  END IF;
  SELECT * INTO v_artifact FROM public.economics_policy_versions
   WHERE ad_account_id=p_ad_account_id AND id=p_artifact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'economics policy artifact not found or account mismatch'; END IF;
  IF v_artifact.content_hash IS DISTINCT FROM p_expected_hash THEN
    RAISE EXCEPTION 'economics policy hash mismatch';
  END IF;
  IF v_artifact.captured_at>pg_catalog.transaction_timestamp() THEN
    RAISE EXCEPTION 'economics policy artifact capture time has not happened yet';
  END IF;
  SELECT * INTO v_latest_artifact FROM public.economics_policy_versions
   WHERE ad_account_id=p_ad_account_id ORDER BY revision DESC LIMIT 1;
  IF v_latest_artifact.content_hash IS DISTINCT FROM v_artifact.content_hash THEN
    RAISE EXCEPTION 'newer economics policy awaits owner review';
  END IF;
  SELECT * INTO v_prior_approved FROM public.economics_policy_approvals
   WHERE ad_account_id=p_ad_account_id AND decision='approved'
   ORDER BY revision DESC LIMIT 1;
  IF FOUND AND p_effective_from<v_prior_approved.effective_from THEN
    RAISE EXCEPTION 'economics policy effective time cannot move backward';
  END IF;
  INSERT INTO public.economics_policy_approvals(
    ad_account_id,artifact_id,artifact_hash,decision,revision,previous_approval_id,
    effective_from,reviewed_by,reason,review_due_at,dedupe_key,created_at)
  VALUES (
    p_ad_account_id,p_artifact_id,p_expected_hash,'approved',COALESCE(v_previous.revision,0)+1,
    p_expected_previous_approval_id,p_effective_from,p_reviewed_by,p_reason,p_review_due_at,
    p_dedupe_key,pg_catalog.clock_timestamp())
  RETURNING * INTO v_row;
  RETURN v_row;
END
$$;


--
-- Name: landing_page_approvals; Type: TABLE; Schema: public; Owner: -
