CREATE FUNCTION public.withdraw_landing_page_approval(p_ad_account_id uuid, p_canonical_url text, p_expected_current_approval_id uuid, p_reviewed_by text, p_reason text, p_dedupe_key text) RETURNS public.landing_page_approvals
