    CONSTRAINT ad_creative_assignment_observations_source_kind_check CHECK ((source_kind = ANY (ARRAY['migration_baseline'::text, 'meta_sync'::text]))),
    CONSTRAINT ad_creative_assignment_observed_at_finite CHECK (((observed_at > '-infinity'::timestamp with time zone) AND (observed_at < 'infinity'::timestamp with time zone)))
);


