    targeting_last_synced_at timestamp with time zone,
    targeting_optimization_types jsonb,
    delivery_sub_status jsonb,
    delivery_sub_status_read_available boolean DEFAULT false NOT NULL,
    delivery_sub_status_synced_at timestamp with time zone,
    attribution_spec jsonb,
    CONSTRAINT adsets_delivery_sub_status_object CHECK (((delivery_sub_status IS NULL) OR (jsonb_typeof(delivery_sub_status) = 'object'::text))),
    CONSTRAINT adsets_delivery_sub_status_read_state CHECK (((delivery_sub_status_read_available AND (delivery_sub_status_synced_at IS NOT NULL)) OR ((NOT delivery_sub_status_read_available) AND (delivery_sub_status IS NULL) AND (delivery_sub_status_synced_at IS NULL))))
);


--
-- Name: COLUMN adsets.learning_stage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.learning_stage IS 'Meta learning_stage_info.status (LEARNING | LEARNING_LIMITED | SUCCESS). SUCCESS = exited learning. Synced from the adset node; null when unknown.';


--
-- Name: COLUMN adsets.learning_conversions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.learning_conversions IS 'Meta learning_stage_info.conversions — optimization events counted toward learning exit (~50 needed within 7 days of the last significant edit). Attribution-scoped; RESETS on significant edits. Not lifetime performance. Null when unknown.';


--
-- Name: COLUMN adsets.last_sig_edit_ts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.last_sig_edit_ts IS 'Meta learning_stage_info.last_sig_edit_ts — when the ad set was last significantly edited (learning phase and its conversion counter reset from this moment). Null when unknown.';


--
-- Name: COLUMN adsets.targeting_last_synced_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.targeting_last_synced_at IS 'When the TARGETING SPEC specifically was last refetched from Meta. Distinct from last_synced_at, which advances on any sync. NULL = unknown age, which the audience resolver treats as STALE and freezes on.';


--
-- Name: COLUMN adsets.targeting_optimization_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.targeting_optimization_types IS 'Meta sibling ad-set field: what Meta actually relaxed (detailed_targeting / lookalike). NULL = not reported by Meta, which is NOT the same as "nothing relaxed". Configured expansion state lives in targeting.targeting_automation.advantage_audience (modern) or targeting.targeting_optimization (legacy).';


--
-- Name: COLUMN adsets.delivery_sub_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.delivery_sub_status IS 'Normalized Meta delivery_sub_status payload. NULL may mean a successful empty read or unavailable; inspect delivery_sub_status_read_available.';


--
-- Name: COLUMN adsets.attribution_spec; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.adsets.attribution_spec IS 'Latest Meta-observed ad-set attribution_spec. NULL means not observed, never an assumed window.';


