    CONSTRAINT causal_coverage_member_hash CHECK ((unit_key_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT causal_coverage_member_time CHECK ((isfinite(effective_from) AND isfinite(effective_through) AND (effective_through > effective_from) AND isfinite(recorded_at)))
);


