    import_sequence bigint NOT NULL,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT causal_contribution_cost_cut_recorded CHECK (isfinite(recorded_at)),
    CONSTRAINT causal_contribution_cost_cut_source CHECK ((cost_source ~ '^[a-z][a-z0-9_]{1,63}$'::text))
);


--
-- Name: causal_contribution_unit_outcomes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.causal_contribution_unit_outcomes (
    generation_id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    experiment_id uuid NOT NULL,
    design_version_id uuid NOT NULL,
    design_approval_id uuid NOT NULL,
    assignment_unit_id uuid NOT NULL,
    arm text NOT NULL,
    outcome_count integer NOT NULL,
    collected_ex_tax_minor bigint NOT NULL,
    refunds_ex_tax_minor bigint NOT NULL,
    chargebacks_ex_tax_minor bigint NOT NULL,
    recovered_chargebacks_ex_tax_minor bigint NOT NULL,
    payment_fees_minor bigint NOT NULL,
    variable_cost_minor bigint NOT NULL,
    ad_spend_minor bigint NOT NULL,
    contribution_minor bigint NOT NULL,
    currency text NOT NULL,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT causal_contribution_unit_amounts CHECK (((collected_ex_tax_minor >= 0) AND (refunds_ex_tax_minor >= 0) AND (chargebacks_ex_tax_minor >= 0) AND (recovered_chargebacks_ex_tax_minor >= 0) AND (variable_cost_minor >= 0) AND (ad_spend_minor >= 0))),
    CONSTRAINT causal_contribution_unit_arm CHECK ((arm = ANY (ARRAY['treatment'::text, 'comparator'::text]))),
    CONSTRAINT causal_contribution_unit_counts CHECK ((outcome_count >= 0)),
    CONSTRAINT causal_contribution_unit_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT causal_contribution_unit_formula CHECK ((contribution_minor = ((((((collected_ex_tax_minor - refunds_ex_tax_minor) - chargebacks_ex_tax_minor) + recovered_chargebacks_ex_tax_minor) - payment_fees_minor) - variable_cost_minor) - ad_spend_minor))),
    CONSTRAINT causal_contribution_unit_recorded CHECK (isfinite(recorded_at))
);


--
-- Name: TABLE causal_contribution_unit_outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.causal_contribution_unit_outcomes IS 'Every assigned unit, including zero-outcome and negative-contribution units, in integer minor units of the row''s currency.';


