    source_fingerprint text NOT NULL,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT causal_meta_spend_day_amount CHECK (((spend_minor >= 0) AND (spend_minor <= '100000000000'::bigint))),
    CONSTRAINT causal_meta_spend_day_fingerprint CHECK ((source_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT causal_meta_spend_day_recorded CHECK (isfinite(recorded_at))
);


--
-- Name: TABLE causal_meta_spend_days; Type: COMMENT; Schema: public; Owner: -
