--
-- Name: conversion_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversion_deliveries (
    id bigint NOT NULL,
    outcome_id uuid NOT NULL,
    event_id text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    value_sent numeric,
    currency_sent text,
    send_mode text NOT NULL,
    events_received integer,
    accepted_at timestamp with time zone,
    delivered_at timestamp with time zone,
    error_state text,
    error_class text,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    api_version text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_event_time timestamp with time zone,
    accepted_value numeric,
    accepted_currency text,
    accepted_send_mode text,
    accepted_events_received integer,
    accepted_api_version text,
    last_attempt_event_time timestamp with time zone,
    last_attempt_value numeric,
    last_attempt_currency text,
    last_attempt_send_mode text,
    last_attempt_events_received integer,
    last_attempt_error_state text,
    last_attempt_error_class text,
    last_attempt_api_version text,
    accepted_attempt_count integer DEFAULT 0 NOT NULL,
    failed_attempt_count integer DEFAULT 0 NOT NULL,
    live_accepted_at timestamp with time zone,
    test_accepted_at timestamp with time zone,
    test_accepted_count integer DEFAULT 0 NOT NULL,
    platform text DEFAULT 'meta'::text NOT NULL,
    CONSTRAINT conversion_deliveries_platform_check CHECK ((platform = ANY (ARRAY['meta'::text]))),
    CONSTRAINT conversion_delivery_send_mode_chk CHECK ((send_mode = ANY (ARRAY['live'::text, 'test'::text])))
);


--
-- Name: TABLE conversion_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conversion_deliveries IS 'Per-event server CAPI delivery lineage keyed by the deterministic event_id (derived from the outcome source identity; Acuity rows keep acuity-<id>). accepted_at = Meta accepted (events_received = 1, no error). delivered_at = this database durably recorded it. Both being set is the ONLY proof of delivery; an HTTP 2xx alone is not.';


--
-- Name: COLUMN conversion_deliveries.events_received; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.events_received IS 'Verbatim events_received from Meta. Exactly 1 is success. 0 means Meta accepted the request but no event; >1 means the payload was not the single event we believe we sent.';


--
-- Name: COLUMN conversion_deliveries.error_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.error_class IS 'Redacted error class only (e.g. http_error, meta_error, invalid_json). Never a token, signed URL, or customer value.';


--
-- Name: COLUMN conversion_deliveries.accepted_event_time; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.accepted_event_time IS 'IMMUTABLE once set. The event_time Meta actually accepted. A later retry can never restate it.';


--
-- Name: COLUMN conversion_deliveries.last_attempt_error_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.last_attempt_error_state IS 'MUTABLE. The most recent attempt''s outcome. A failure here does NOT invalidate an earlier acceptance.';


--
-- Name: COLUMN conversion_deliveries.accepted_attempt_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.accepted_attempt_count IS 'How many attempts Meta accepted. >1 means we re-sent an already-accepted deterministic event_id (safe: Meta dedups), not a double conversion.';


--
-- Name: COLUMN conversion_deliveries.live_accepted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.live_accepted_at IS 'When Meta accepted a LIVE send. The ONLY acceptance that is delivery evidence; the only one that stamps outcomes.conversion_sent_at. Immutable once set.';


--
-- Name: COLUMN conversion_deliveries.test_accepted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_deliveries.test_accepted_at IS 'When Meta accepted a TEST-mode send. Recorded for rehearsal visibility ONLY: never delivery evidence, and never a blocker for a later live acceptance.';


--
-- Name: conversion_deliveries_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.conversion_deliveries_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: conversion_deliveries_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.conversion_deliveries_id_seq OWNED BY public.conversion_deliveries.id;


