    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT creative_vision_analysis_version_source_asset_fingerprint_check CHECK ((source_asset_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT creative_vision_analysis_versions_analysis_check CHECK (((jsonb_typeof(analysis) = 'object'::text) AND (analysis ?& ARRAY['format'::text, 'has_text_overlay'::text, 'hook_text'::text, 'shows_price'::text, 'talent_type'::text, 'setting'::text, 'color_mood'::text, 'cta_visible'::text, 'hook_strength_score'::text, 'notes'::text]) AND (((((((((((analysis - 'format'::text) - 'has_text_overlay'::text) - 'hook_text'::text) - 'shows_price'::text) - 'talent_type'::text) - 'setting'::text) - 'color_mood'::text) - 'cta_visible'::text) - 'hook_strength_score'::text) - 'notes'::text) = '{}'::jsonb) AND ((analysis ->> 'format'::text) = ANY (ARRAY['video'::text, 'static'::text, 'carousel'::text])) AND (jsonb_typeof((analysis -> 'has_text_overlay'::text)) = 'boolean'::text) AND (((analysis -> 'hook_text'::text) = 'null'::jsonb) OR ((jsonb_typeof((analysis -> 'hook_text'::text)) = 'string'::text) AND (length((analysis ->> 'hook_text'::text)) <= 500))) AND (jsonb_typeof((analysis -> 'shows_price'::text)) = 'boolean'::text) AND ((analysis ->> 'talent_type'::text) = ANY (ARRAY['solo'::text, 'group'::text, 'broll'::text, 'none'::text])) AND ((analysis ->> 'setting'::text) = ANY (ARRAY['studio'::text, 'outdoor'::text, 'other'::text])) AND ((analysis ->> 'color_mood'::text) = ANY (ARRAY['bright'::text, 'dark'::text, 'warm'::text, 'neutral'::text])) AND (jsonb_typeof((analysis -> 'cta_visible'::text)) = 'boolean'::text) AND (jsonb_typeof((analysis -> 'hook_strength_score'::text)) = 'number'::text) AND ((((analysis ->> 'hook_strength_score'::text))::numeric >= (1)::numeric) AND (((analysis ->> 'hook_strength_score'::text))::numeric <= (5)::numeric)) AND (((analysis ->> 'hook_strength_score'::text))::numeric = trunc(((analysis ->> 'hook_strength_score'::text))::numeric)) AND (((analysis -> 'notes'::text) = 'null'::jsonb) OR ((jsonb_typeof((analysis -> 'notes'::text)) = 'string'::text) AND (length((analysis ->> 'notes'::text)) <= 1000))))),
    CONSTRAINT creative_vision_analysis_versions_analysis_fingerprint_check CHECK ((analysis_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT creative_vision_analysis_versions_analysis_schema_version_check CHECK (((analysis_schema_version >= 1) AND (analysis_schema_version <= 2147483647))),
    CONSTRAINT creative_vision_analysis_versions_analyzed_at_check CHECK (((analyzed_at > '-infinity'::timestamp with time zone) AND (analyzed_at < 'infinity'::timestamp with time zone))),
    CONSTRAINT creative_vision_analysis_versions_meta_creative_id_check CHECK ((meta_creative_id ~ '^[0-9]{1,32}$'::text)),
    CONSTRAINT creative_vision_analysis_versions_model_check CHECK (((model = btrim(model)) AND ((length(model) >= 1) AND (length(model) <= 128)))),
    CONSTRAINT creative_vision_analysis_versions_prompt_fingerprint_check CHECK ((prompt_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT creative_vision_analysis_versions_prompt_version_check CHECK ((prompt_version ~ '^[a-z][a-z0-9-]{0,63}$'::text)),
    CONSTRAINT creative_vision_analysis_versions_provider_check CHECK ((provider = ANY (ARRAY['anthropic'::text, 'openai'::text])))
);


