--
-- Name: daily_digest_delivery_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.daily_digest_delivery_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    provider text NOT NULL,
    recipient text NOT NULL,
    payload_fingerprint text NOT NULL,
    message_id text NOT NULL,
    status text DEFAULT 'claimed'::text NOT NULL,
    provider_message_id text,
    claimed_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT daily_digest_delivery_attempt_state_valid CHECK ((((status = 'claimed'::text) AND (completed_at IS NULL) AND (provider_message_id IS NULL)) OR ((status = ANY (ARRAY['sent'::text, 'failed'::text, 'ambiguous'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT daily_digest_delivery_attempts_message_id_check CHECK (((message_id = btrim(message_id)) AND ((length(message_id) >= 3) AND (length(message_id) <= 320)) AND (message_id !~ '[[:cntrl:]]'::text))),
    CONSTRAINT daily_digest_delivery_attempts_payload_fingerprint_check CHECK ((payload_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT daily_digest_delivery_attempts_provider_check CHECK ((provider = ANY (ARRAY['gmail_smtp'::text, 'resend'::text]))),
    CONSTRAINT daily_digest_delivery_attempts_provider_message_id_check CHECK (((provider_message_id IS NULL) OR ((provider_message_id = btrim(provider_message_id)) AND ((length(provider_message_id) >= 1) AND (length(provider_message_id) <= 512)) AND (provider_message_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT daily_digest_delivery_attempts_recipient_check CHECK (((recipient = btrim(recipient)) AND ((length(recipient) >= 3) AND (length(recipient) <= 320)) AND (recipient ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text) AND (recipient !~ '[<>,;]'::text))),
    CONSTRAINT daily_digest_delivery_attempts_status_check CHECK ((status = ANY (ARRAY['claimed'::text, 'sent'::text, 'failed'::text, 'ambiguous'::text])))
);


--
-- Name: TABLE daily_digest_delivery_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.daily_digest_delivery_attempts IS 'Durable one-shot claims for digest email; ambiguous SMTP outcomes are intentionally not retried.';


--
-- Name: daily_insights; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.daily_insights (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    date_start date NOT NULL,
    date_stop date NOT NULL,
    entity_level public.entity_level NOT NULL,
    ad_account_id uuid NOT NULL,
    campaign_id uuid,
    adset_id uuid,
    ad_id uuid,
    meta_account_id text,
    meta_campaign_id text,
    meta_adset_id text,
    meta_ad_id text,
    impressions bigint DEFAULT 0 NOT NULL,
    reach bigint DEFAULT 0 NOT NULL,
    frequency numeric(8,4),
    spend numeric DEFAULT 0 NOT NULL,
    clicks bigint DEFAULT 0 NOT NULL,
    unique_clicks bigint DEFAULT 0 NOT NULL,
    link_clicks bigint,
    landing_page_views bigint,
    ctr numeric(10,6),
    cpc numeric,
    cpm numeric,
    leads bigint DEFAULT 0 NOT NULL,
    bookings bigint DEFAULT 0 NOT NULL,
    cost_per_lead numeric,
    cost_per_booking numeric,
    video_views bigint,
    video_thru_plays bigint,
    video_avg_play_time numeric(10,4),
    video_p25_watched bigint,
    video_p50_watched bigint,
    video_p75_watched bigint,
    video_p100_watched bigint,
    actions jsonb,
    action_values jsonb,
    cost_per_action_type jsonb,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    appointment_value numeric,
    roas numeric(10,4),
    thruplay_count integer,
    video_p25 integer,
    video_p50 integer,
    video_p75 integer,
    video_p100 integer,
    video_3s_views integer,
    hook_rate numeric(8,4),
    hold_rate numeric(8,4),
    quality_ranking text,
    engagement_rate_ranking text,
    conversion_rate_ranking text,
    bookings_view_through integer,
    video_plays bigint,
    video_continuous_2s_views bigint,
    early_view_source text,
    derived_metric_warnings jsonb,
    video_metrics_contract text,
    conversion_values jsonb,
    appointment_value_view_through numeric,
    CONSTRAINT chk_entity_nulls CHECK ((((entity_level = 'account'::public.entity_level) AND (campaign_id IS NULL) AND (adset_id IS NULL) AND (ad_id IS NULL)) OR ((entity_level = 'campaign'::public.entity_level) AND (campaign_id IS NOT NULL) AND (adset_id IS NULL) AND (ad_id IS NULL)) OR ((entity_level = 'adset'::public.entity_level) AND (campaign_id IS NOT NULL) AND (adset_id IS NOT NULL) AND (ad_id IS NULL)) OR ((entity_level = 'ad'::public.entity_level) AND (campaign_id IS NOT NULL) AND (adset_id IS NOT NULL) AND (ad_id IS NOT NULL)))),
    CONSTRAINT daily_insights_video_contract_chk CHECK (((video_metrics_contract IS NULL) OR (video_metrics_contract = 'rev_i'::text)))
);


--
-- Name: COLUMN daily_insights.video_views; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_views IS 'Video STARTS (video_play_actions) on rev_i rows; NULL when Meta returned no start count. On legacy rows (video_metrics_contract NULL) this column held the p25 retention milestone and has been NEUTRALISED to NULL — a wrong number removed, never relabelled.';


--
-- Name: COLUMN daily_insights.video_thru_plays; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_thru_plays IS 'ThruPlay: a 15-second view, or a complete play of a video shorter than 15s. Kept SEPARATE from the retention milestones — on a long video ThruPlay can exceed the 25% milestone count, which is why thruplays/p25 was never a valid "hold rate".';


--
-- Name: COLUMN daily_insights.video_p25_watched; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_p25_watched IS 'RETENTION MILESTONE: viewers reaching 25% of the video length. On a 60-120s creative that is ~15-30 seconds of watch time. NEVER interpret as a three-second hook.';


--
-- Name: COLUMN daily_insights.video_p50_watched; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_p50_watched IS 'RETENTION MILESTONE: viewers reaching 50% of the video length.';


--
-- Name: COLUMN daily_insights.video_p75_watched; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_p75_watched IS 'RETENTION MILESTONE: viewers reaching 75% of the video length.';


--
-- Name: COLUMN daily_insights.video_p100_watched; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_p100_watched IS 'RETENTION MILESTONE: viewers reaching 100% of the video length.';


--
-- Name: COLUMN daily_insights.hook_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.hook_rate IS 'EARLY-VIEW rate (video starts or continuous-2s views over impressions) on rev_i rows. NULL on legacy rows (video_metrics_contract NULL), where it was derived from the p25 proxy.';


--
-- Name: COLUMN daily_insights.hold_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.hold_rate IS 'RETIRED. Always NULL. It was thruplays/p25, which can exceed 100% on a long video. Use thruplay_rate (over impressions) and the retention milestones.';


--
-- Name: COLUMN daily_insights.video_plays; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_plays IS 'video_play_actions: the number of times the video STARTED to play. This is a video start, NOT a three-second view. Meta documents this field as "in development"; NULL when the response omitted it.';


--
-- Name: COLUMN daily_insights.video_continuous_2s_views; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_continuous_2s_views IS 'video_continuous_2_sec_watched_actions: continuous 2-second views. NOT a three-second view.';


--
-- Name: COLUMN daily_insights.early_view_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.early_view_source IS 'Which real field the early-view rate was computed from, or ''unavailable''. p25 is NEVER a valid source — it is a retention milestone (25% of video length), not an early view.';


--
-- Name: COLUMN daily_insights.derived_metric_warnings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.derived_metric_warnings IS 'Raw inputs preserved for any derived rate whose raw relationship was impossible (e.g. >100%). A clamp without one of these rows is a bug: silent clamping hides a real data problem.';


--
-- Name: COLUMN daily_insights.video_metrics_contract; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.video_metrics_contract IS 'NULL = legacy row: video_views held the p25 RETENTION MILESTONE, and hook/hold were derived from that invalid proxy. ''rev_i'' = video_views is a genuine video-START count (or NULL) and every derived rate carries its denominator contract. Trends must EXCLUDE or LABEL null-contract rows.';


--
-- Name: COLUMN daily_insights.conversion_values; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.conversion_values IS 'Meta insights `conversion_values` as returned. The only field that still breaks a custom pixel event''s value out BY NAME (e.g. offsite_conversion.fb_pixel_custom.AppointmentConfirmed). NULL = not captured (row predates 2026-08-31 or the field was absent), which is NOT the same as an empty array.';


--
-- Name: COLUMN daily_insights.appointment_value_view_through; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_insights.appointment_value_view_through IS 'Portion of appointment_value attributed to 1d_view. 0 = Meta reported other windows but not this one (a measured zero). NULL = no window breakdown reported at all (unknown).';


--
-- Name: daily_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.daily_reports (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    ad_account_id uuid NOT NULL,
    report_date date NOT NULL,
    summary_text text,
    full_report_md text,
    report_json jsonb,
    total_spend numeric,
    total_leads bigint,
    total_bookings bigint,
    avg_cpl numeric,
    avg_cpb numeric,
    model_used text,
    prompt_tokens integer,
    completion_tokens integer,
    generation_ms integer,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    business_outcomes integer,
    business_revenue numeric,
    recommendation_generation_id uuid,
    money_basis_version integer NOT NULL,
    business_revenue_basis text NOT NULL,
    outcome_source_available boolean,
    business_revenue_complete boolean,
    collected_value_lower_bound numeric,
    collected_value_covered_outcomes integer,
    collected_value_total_outcomes integer,
    executive_evidence_generation_id uuid,
    CONSTRAINT daily_reports_money_basis_contract CHECK ((((money_basis_version = 0) AND (business_revenue_basis = 'legacy_unversioned'::text) AND (outcome_source_available IS NULL) AND (business_revenue_complete IS NULL) AND (collected_value_lower_bound IS NULL) AND (collected_value_covered_outcomes IS NULL) AND (collected_value_total_outcomes IS NULL)) OR ((money_basis_version = 1) AND (business_revenue_basis = 'outcome_collected_value'::text) AND (outcome_source_available IS NOT NULL) AND (((NOT outcome_source_available) AND (business_revenue_complete IS NULL) AND (collected_value_lower_bound IS NULL) AND (collected_value_covered_outcomes IS NULL) AND (collected_value_total_outcomes IS NULL) AND (business_revenue IS NULL)) OR (outcome_source_available AND (business_revenue_complete IS NOT NULL) AND (collected_value_lower_bound >= (0)::numeric) AND (collected_value_covered_outcomes >= 0) AND (collected_value_total_outcomes >= collected_value_covered_outcomes) AND ((business_revenue_complete AND (collected_value_covered_outcomes = collected_value_total_outcomes) AND (business_revenue IS NOT NULL) AND (business_revenue = collected_value_lower_bound)) OR ((NOT business_revenue_complete) AND (collected_value_covered_outcomes < collected_value_total_outcomes) AND (business_revenue IS NULL))))))))
);


--
-- Name: COLUMN daily_reports.business_outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_reports.business_outcomes IS 'Canonical outcomes from the enabled outcome sources (non-cancelled) for the report window, by account-timezone outcome date. Business truth; total_bookings stays the Meta-attributed estimate.';


--
-- Name: COLUMN daily_reports.business_revenue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_reports.business_revenue IS 'Versioned checkout revenue. For money_basis_version=1 this equals complete outcome collected_value (Acuity: amount_paid) over active outcomes; NULL when coverage is incomplete. Legacy v0 rows may contain scheduled booked value.';


--
-- Name: COLUMN daily_reports.collected_value_lower_bound; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_reports.collected_value_lower_bound IS 'Observed sum of non-null outcome collected values (Acuity: amount_paid). Diagnostic lower bound only when revenue coverage is incomplete.';


--
-- Name: COLUMN daily_reports.executive_evidence_generation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.daily_reports.executive_evidence_generation_id IS 'Exact immutable ExecutiveEvidenceSnapshotV1 used by a current DailyDigestV3.';


--
-- Name: daypart_insights; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.daypart_insights (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    ad_account_id uuid,
    date_range_start date NOT NULL,
    date_range_end date NOT NULL,
