    cpa numeric,
    ctr numeric(10,6),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT daypart_insights_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT daypart_insights_hour_of_day_check CHECK (((hour_of_day >= 0) AND (hour_of_day <= 23)))
);


--
-- Name: decision_generations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.decision_generations (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
