    is_current boolean DEFAULT true NOT NULL,
    structural_closures integer DEFAULT 0 NOT NULL,
    orphan_closures integer DEFAULT 0 NOT NULL,
    unknown_metadata_flags integer DEFAULT 0 NOT NULL,
    budget_decisions_frozen boolean DEFAULT false NOT NULL,
    rolled_back_at timestamp with time zone,
    CONSTRAINT decision_generations_kind_check CHECK ((kind = ANY (ARRAY['flag'::text, 'recommendation'::text])))
);


--
-- Name: executive_evidence_generations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.executive_evidence_generations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    report_date date NOT NULL,
    contract_version integer NOT NULL,
    evidence_json jsonb NOT NULL,
    evidence_fingerprint text NOT NULL,
    source_generated_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT executive_evidence_contract CHECK (((jsonb_typeof(evidence_json) = 'object'::text) AND ((evidence_json ->> 'contract'::text) = 'executive_evidence_snapshot'::text) AND ((evidence_json ->> 'version'::text) = '1'::text) AND ((evidence_json #>> '{account,id}'::text[]) = (ad_account_id)::text) AND ((evidence_json ->> 'lastCompleteDate'::text) = (report_date)::text) AND ((evidence_json #>> '{authority,tier}'::text[]) = 'diagnostic_only'::text) AND ((evidence_json #>> '{authority,moneyActionsAuthorized}'::text[]) = 'false'::text))),
    CONSTRAINT executive_evidence_generations_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT executive_evidence_generations_evidence_fingerprint_check CHECK ((evidence_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE executive_evidence_generations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.executive_evidence_generations IS 'Append-only diagnostic evidence snapshots shared by current daily and weekly executive reports.';


--
-- Name: experiments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.experiments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    hypothesis text NOT NULL,
    changed_variable text NOT NULL,
    control_ref text NOT NULL,
    challenger_ref text NOT NULL,
    invariants jsonb DEFAULT '{}'::jsonb NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    primary_metric text NOT NULL,
    guardrails jsonb DEFAULT '[]'::jsonb NOT NULL,
    min_sample integer DEFAULT 0 NOT NULL,
    min_spend numeric DEFAULT 0 NOT NULL,
    success_contract text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    outcome text,
    stop_reason text,
    owner_decision text,
    owner_decided_at timestamp with time zone,
    result_provenance jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    entity_level text,
    entity_ref text,
    CONSTRAINT experiments_complete_needs_outcome CHECK (((status <> 'complete'::text) OR (outcome IS NOT NULL))),
    CONSTRAINT experiments_end_after_start CHECK (((ended_at IS NULL) OR (started_at IS NULL) OR (ended_at >= started_at))),
    CONSTRAINT experiments_ended_needs_end CHECK (((status <> ALL (ARRAY['stopped'::text, 'complete'::text])) OR (ended_at IS NOT NULL))),
    CONSTRAINT experiments_entity_identity_paired CHECK (((entity_level IS NULL) = (entity_ref IS NULL))),
    CONSTRAINT experiments_entity_level_chk CHECK (((entity_level IS NULL) OR (entity_level = ANY (ARRAY['campaign'::text, 'adset'::text, 'ad'::text])))),
    CONSTRAINT experiments_entity_ref_nonblank CHECK (((entity_ref IS NULL) OR (btrim(entity_ref) <> ''::text))),
    CONSTRAINT experiments_floors_nonnegative CHECK (((min_sample >= 0) AND (min_spend >= (0)::numeric))),
    CONSTRAINT experiments_outcome_chk CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['success'::text, 'failure'::text, 'inconclusive'::text])))),
    CONSTRAINT experiments_owner_decision_needs_time CHECK (((owner_decision IS NULL) = (owner_decided_at IS NULL))),
    CONSTRAINT experiments_running_needs_real_floors CHECK (((status <> ALL (ARRAY['running'::text, 'complete'::text])) OR ((min_sample > 0) AND (min_spend > (0)::numeric)))),
    CONSTRAINT experiments_running_needs_start CHECK (((status <> ALL (ARRAY['running'::text, 'stopped'::text, 'complete'::text])) OR (started_at IS NOT NULL))),
    CONSTRAINT experiments_status_chk CHECK ((status = ANY (ARRAY['draft'::text, 'proposed'::text, 'running'::text, 'stopped'::text, 'complete'::text, 'abandoned'::text]))),
    CONSTRAINT experiments_stopped_needs_reason CHECK (((status <> 'stopped'::text) OR (stop_reason IS NOT NULL)))
);


--
-- Name: TABLE experiments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.experiments IS 'Durable test briefs and results. A brief is written BEFORE the run with exactly one changed variable, explicit invariants, a pre-registered primary metric, guardrails, sample/spend floors and a success contract. Maxx generates briefs; only owner_decision authorises action. Write mode stays OFF.';


--
-- Name: COLUMN experiments.changed_variable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.experiments.changed_variable IS 'The ONE variable under test. The partial unique index guarantees at most one RUNNING experiment per variable per account, so concurrent tests cannot contaminate each other.';


--
-- Name: COLUMN experiments.success_contract; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.experiments.success_contract IS 'Success/failure/inconclusive definition committed BEFORE the run. A criterion chosen after seeing the data is not evidence.';


--
-- Name: COLUMN experiments.owner_decision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.experiments.owner_decision IS 'The human decision on the result. Maxx never writes an action from an experiment outcome by itself.';


--
-- Name: COLUMN experiments.entity_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.experiments.entity_level IS 'campaign | adset | ad — the level the experiment runs at. With entity_ref this is the EXACT match key for causal applicability and running-conflict detection; the free-text control_ref/challenger_ref are human-readable only and must never be parsed for identity.';


--
-- Name: COLUMN experiments.entity_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.experiments.entity_ref IS 'The stable entity id this experiment runs on. Exact-matched — never substring-searched out of prose.';


