    CONSTRAINT meta_setup_generations_entity_count_nonnegative CHECK ((entity_count >= 0)),
    CONSTRAINT meta_setup_generations_fingerprint_shape CHECK (((generation_fingerprint IS NULL) OR (generation_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)))
);


