    CONSTRAINT outcome_collected_value_observation_chronology CHECK ((created_at >= observed_at)),
    CONSTRAINT outcome_collected_value_observations_change_kind_check CHECK ((change_kind = ANY (ARRAY['first_observation'::text, 'collected_value_change'::text, 'cancellation_state_change'::text, 'amount_and_state_change'::text]))),
    CONSTRAINT outcome_collected_value_observations_new_collected_value_check CHECK (((new_collected_value IS NULL) OR (new_collected_value >= (0)::numeric))),
    CONSTRAINT outcome_collected_value_observations_observation_source_check CHECK (((length(btrim(observation_source)) >= 1) AND (length(btrim(observation_source)) <= 64))),
    CONSTRAINT outcome_collected_value_observations_old_collected_value_check CHECK (((old_collected_value IS NULL) OR (old_collected_value >= (0)::numeric))),
    CONSTRAINT outcome_collected_value_observations_provenance_check CHECK ((provenance = 'prospective_observation'::text))
);

ALTER TABLE ONLY public.outcome_collected_value_observations FORCE ROW LEVEL SECURITY;


