    CONSTRAINT outcome_csv_imports_counts_check CHECK (((file_bytes >= 0) AND (row_count >= 0) AND (new_count >= 0) AND (changed_count >= 0) AND (unchanged_count >= 0) AND (invalid_count >= 0) AND ((((new_count + changed_count) + unchanged_count) + invalid_count) = row_count))),
    CONSTRAINT outcome_csv_imports_sha256_check CHECK ((file_sha256 ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE outcome_csv_imports; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outcome_csv_imports IS 'One row per committed CSV outcome import: the owner (auth user id), the file SHA-256 (of its UTF-8 text) and size, and how many rows were new, changed, unchanged or invalid. Written only by commit_outcome_csv_import.';


--
-- Name: outcome_observations; Type: TABLE; Schema: public; Owner: -
--

