    CONSTRAINT outcome_sources_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 128)))
);


--
-- Name: TABLE outcome_sources; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outcome_sources IS 'Where an account''s business outcomes come from (csv, signed webhook, or the Acuity example adapter). Disabled by default. config is non-secret: it may name the environment variable that holds a secret, never the secret itself.';


--
-- Name: outcome_touch_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outcome_touch_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
