    linked_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT outcome_touch_link_recording_chronology CHECK ((linked_at >= outcome_created_at)),
    CONSTRAINT outcome_touch_link_time_order CHECK (((first_interaction_at <= last_interaction_at) AND (last_interaction_at <= outcome_created_at))),
    CONSTRAINT outcome_touch_links_policy_version_check CHECK ((policy_version = 1))
);


--
-- Name: TABLE outcome_touch_links; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outcome_touch_links IS 'Immutable linkage created only after a signed outcome webhook (generic, or the Acuity example) establishes a client-created outcome.';


--
-- Name: COLUMN outcome_touch_links.token_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcome_touch_links.token_id IS 'Non-null for normal token-linked outcomes; null for fbclid fallback links created when the intake token was lost but fbclid still matches an identity-complete paid touch.';


--
-- Name: outcome_webhook_deliveries; Type: TABLE; Schema: public; Owner: -
--

