);


--
-- Name: TABLE outcome_webhook_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outcome_webhook_deliveries IS 'Accepted signed webhook deliveries, keyed by the signature digest (the timestamp is inside it). A second delivery with the same digest is a replay. Rows older than one hour are pruned on every claim; the signature tolerance is five minutes, so a pruned digest is already stale.';


--
-- Name: outcomes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outcomes (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    source_id uuid NOT NULL,
    external_id text NOT NULL,
    outcome_type text NOT NULL,
    outcome_label text,
    status text DEFAULT 'confirmed'::text NOT NULL,
    currency character(3) NOT NULL,
    gross_value numeric,
    collected_value numeric,
    occurred_at timestamp with time zone,
    business_date date,
    fulfilment_at timestamp with time zone,
    fulfilment_status text,
    origin text DEFAULT 'unknown'::text,
    first_name text,
    last_name text,
    email text,
    phone text,
    utm_source text,
    utm_medium text,
    utm_campaign text,
    utm_content text,
    utm_term text,
    fbclid text,
    gclid text,
    landing_page text,
    referrer text,
    fbp text,
    raw jsonb,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    conversion_sent_at timestamp with time zone,
    conversion_send_error text,
    initial_gross_value numeric,
    initial_status text,
    initial_observed_at timestamp with time zone,
    initial_observation_source text,
    initial_provenance text DEFAULT 'observed'::text,
    observation_source text,
    origin_observed_at timestamp with time zone,
    origin_observed_source text,
    fbc text,
    conversion_event_id text,
    source_updated_at timestamp with time zone,
    CONSTRAINT outcomes_conversion_event_id_format CHECK (((conversion_event_id IS NULL) OR ((conversion_event_id ~ '^[A-Za-z0-9._:-]{1,100}$'::text) AND (conversion_event_id !~* '^(maxx|acuity)-'::text)))),
    CONSTRAINT outcomes_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT outcomes_external_id_check CHECK (((length(btrim(external_id)) >= 1) AND (length(external_id) <= 256))),
    CONSTRAINT outcomes_fulfilment_status_check CHECK (((fulfilment_status IS NULL) OR (fulfilment_status = ANY (ARRAY['scheduled'::text, 'fulfilled'::text, 'no_show'::text])))),
    CONSTRAINT outcomes_initial_provenance_chk CHECK (((initial_provenance IS NULL) OR (initial_provenance = ANY (ARRAY['observed'::text, 'migration_snapshot'::text])))),
    CONSTRAINT outcomes_initial_status_check CHECK (((initial_status IS NULL) OR (initial_status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'cancelled'::text, 'refunded'::text])))),
    CONSTRAINT outcomes_origin_check CHECK (((origin IS NULL) OR (origin = ANY (ARRAY['website'::text, 'staff_or_manual'::text, 'unknown'::text])))),
    CONSTRAINT outcomes_origin_pair_coherent CHECK (((origin_observed_at IS NULL) = (origin_observed_source IS NULL))),
    CONSTRAINT outcomes_origin_source_domain CHECK (((origin_observed_source IS NULL) OR (origin_observed_source = ANY (ARRAY['webhook'::text, 'backfill_inferred_from_capi_delivery'::text])))),
    CONSTRAINT outcomes_outcome_type_check CHECK ((outcome_type = ANY (ARRAY['lead'::text, 'booking'::text, 'sale'::text, 'signup'::text, 'quote'::text, 'subscription'::text, 'custom'::text]))),
    CONSTRAINT outcomes_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'cancelled'::text, 'refunded'::text])))
);


--
-- Name: TABLE outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outcomes IS 'Canonical business-outcome ledger: one row per result from one outcome source, unique per (account, source, external id). Active collected_value is operational collected revenue after discounts; gross_value is the booked/quoted value. Cancelled rows are excluded from active performance; the ledger alone does not prove refund, settlement, or reschedule state. For Acuity rows external_id is the Acuity appointment id and outcome_type is booking.';


--
-- Name: COLUMN outcomes.external_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.external_id IS 'The source system''s own identifier (Acuity: the appointment id as text). A reschedule keeps the same external_id and row; a cancel-and-rebook is two rows.';


--
-- Name: COLUMN outcomes.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.status IS 'Lifecycle state. cancelled outcomes are excluded from active outcomes and collected revenue; this field alone does not prove a reschedule or refund. Acuity rows are confirmed or cancelled.';


--
-- Name: COLUMN outcomes.currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.currency IS 'ISO 4217 currency of gross_value and collected_value. Acuity rows use the ad account currency. Totals across currencies are refused, never summed.';


--
-- Name: COLUMN outcomes.gross_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.gross_value IS 'Scheduled/charged value used for booked value (Acuity: price). It is separate from collected revenue and must not be substituted for collected_value.';


--
-- Name: COLUMN outcomes.collected_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.collected_value IS 'Owner-confirmed operational collected revenue after discounts for active outcomes (Acuity: amountPaid). NULL is missing coverage, not zero. The processor settlement ledger separately reconciles settlement, refunds, disputes, and fees.';


--
-- Name: COLUMN outcomes.occurred_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.occurred_at IS 'The conversion instant (Acuity: when the booking was created). Attribution and conversions event_time use it.';


--
-- Name: COLUMN outcomes.business_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.business_date IS 'occurred_at converted to the account calendar date (America/New_York today). The outcome moment is the ad-attribution day and the join key to daily ad spend. App-computed via etDateOf.';


--
-- Name: COLUMN outcomes.fulfilment_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.fulfilment_at IS 'When the outcome is fulfilled (Acuity: the appointment start time). Optional.';


--
-- Name: COLUMN outcomes.origin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.origin IS 'Who created the outcome: website (a by-id payload observed a client booking: Acuity scheduledBy present and empty), staff_or_manual (Acuity scheduledBy non-empty; never sent as a website event), unknown (never observed). The raw Acuity value stays in raw.';


--
-- Name: COLUMN outcomes.first_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.first_name IS 'PII. Used only to build hashed user data for conversions matching; never exported or shown.';


--
-- Name: COLUMN outcomes.last_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.last_name IS 'PII. Used only to build hashed user data for conversions matching; never exported or shown.';


--
-- Name: COLUMN outcomes.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.email IS 'PII. Used only to build hashed user data for conversions matching; never exported or shown.';


--
-- Name: COLUMN outcomes.phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.phone IS 'PII. Used only to build hashed user data for conversions matching; never exported or shown.';


--
-- Name: COLUMN outcomes.utm_campaign; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.utm_campaign IS 'From a hidden Internal-Use-Only intake field, populated forward once link decoration ships. Null for all pre-go-live outcomes — GA4 stays the historical attribution lens.';


--
-- Name: COLUMN outcomes.fbp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.fbp IS 'Browser _fbp captured by the CAPI relay at confirmation (R3); attached to server sends when present.';


--
-- Name: COLUMN outcomes.conversion_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.conversion_sent_at IS 'Timestamp of the successful LIVE server-side conversion delivery (event_id acuity-<external id> for Acuity). Never set by test-mode sends (R2).';


--
-- Name: COLUMN outcomes.conversion_send_error; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.conversion_send_error IS 'Conversion send failure, or terminal skip: staff_created (R4) / expired (R1) / missed-48h-window. Null = not yet attempted or delivered clean.';


--
-- Name: COLUMN outcomes.initial_gross_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.initial_gross_value IS 'gross_value at the FIRST observation of this outcome. Meaningful only when initial_provenance = ''observed''; for ''migration_snapshot'' rows this is the mutable value at migration time and is NOT an outcome-time value.';


--
-- Name: COLUMN outcomes.initial_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.initial_status IS 'status at the first observation. Same provenance caveat as initial_gross_value.';


--
-- Name: COLUMN outcomes.initial_provenance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.initial_provenance IS '''observed'' = captured live by the trigger at first INSERT (a real first observation). ''migration_snapshot'' = backfilled from an already-mutable row; never call it outcome-time value.';


--
-- Name: COLUMN outcomes.observation_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.observation_source IS 'Writer-declared source of the CURRENT write: webhook | sweep | backfill | manual. Read by the observation trigger; NULL is recorded as ''unknown''.';


--
-- Name: COLUMN outcomes.origin_observed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.origin_observed_at IS 'When the origin was ACTUALLY OBSERVED (Acuity: the scheduledBy key in a by-id payload). Distinct from observation_source, which names the most recent writer and is overwritten by every sweep. NULL means the origin was never established — the outcome''s conversion eligibility is UNKNOWN, not proven ineligible.';


--
-- Name: COLUMN outcomes.origin_observed_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.origin_observed_source IS 'How the origin fact was established. EXACTLY TWO legal values, enforced by outcomes_origin_source_domain: ''webhook'' = a by-id payload actually carried the origin (evidence); ''backfill_inferred_from_capi_delivery'' = INFERRED from delivery evidence already on the row (an inference, NOT an observation). A LIST endpoint cannot establish origin, so neither the nightly sweep nor scripts/backfill-acuity.ts may write this column. NULL means the origin was never established: eligibility is UNKNOWN, not proven ineligible. This CHECK constrains VOCABULARY ONLY; the application writer enforces who may write it.';


--
-- Name: COLUMN outcomes.fbc; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.fbc IS 'Browser _fbc (fb.1.<creation ms>.<fbclid>) supplied by a webhook sender. Attached to conversions only when its creation time is not after occurred_at.';


--
-- Name: COLUMN outcomes.conversion_event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.conversion_event_id IS 'Sender-supplied conversion event id (webhook sources only), shared with the business''s browser pixel so Meta deduplicates. NULL: the derived id (maxx-<outcome uuid>) is used. Set once; never changes.';


--
-- Name: COLUMN outcomes.source_updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outcomes.source_updated_at IS 'The sender''s own version time for this outcome (webhook `updated_at`). A delivery with an older one is not applied. NULL: arrival order.';


--
-- Name: paid_attribution_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_attribution_tokens (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    touch_id uuid NOT NULL,
    first_touch_id uuid NOT NULL,
    last_touch_id uuid NOT NULL,
    previous_token_id uuid,
    token_hash text NOT NULL,
    policy_version integer NOT NULL,
    issued_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_attribution_tokens_policy_version_check CHECK ((policy_version = 1)),
    CONSTRAINT paid_attribution_tokens_token_hash_check CHECK ((token_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT paid_token_time_order CHECK ((expires_at > issued_at))
);


--
-- Name: TABLE paid_attribution_tokens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_attribution_tokens IS 'Opaque-token digests and immutable first/last paid-touch lineage. Raw bearer tokens are never stored.';


--
-- Name: paid_capture_attempt_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_capture_attempt_events (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    outcome text NOT NULL,
    reason_code text,
    touch_id uuid,
    token_id uuid,
    contract_version integer NOT NULL,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_capture_attempt_events_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_capture_attempt_events_outcome_check CHECK ((outcome = ANY (ARRAY['rejected_invalid'::text, 'rejected_previous_token'::text, 'capture_conflict'::text, 'storage_failed'::text, 'touch_persisted'::text, 'token_response_issued'::text]))),
    CONSTRAINT paid_capture_attempt_events_reason_code_check CHECK (((reason_code IS NULL) OR ((length(btrim(reason_code)) >= 1) AND (length(btrim(reason_code)) <= 128)))),
    CONSTRAINT paid_capture_event_chronology CHECK ((created_at >= recorded_at)),
    CONSTRAINT paid_capture_event_fact_shape CHECK ((((outcome = ANY (ARRAY['touch_persisted'::text, 'token_response_issued'::text])) AND (reason_code IS NULL) AND (touch_id IS NOT NULL) AND (token_id IS NOT NULL)) OR ((outcome <> ALL (ARRAY['touch_persisted'::text, 'token_response_issued'::text])) AND (reason_code IS NOT NULL) AND (touch_id IS NULL) AND (token_id IS NULL))))
);

ALTER TABLE ONLY public.paid_capture_attempt_events FORCE ROW LEVEL SECURITY;


--
-- Name: paid_capture_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_capture_attempts (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    browser_capture_id uuid,
    request_fingerprint text NOT NULL,
    received_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    contract_version integer NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_capture_attempt_chronology CHECK ((created_at >= received_at)),
    CONSTRAINT paid_capture_attempts_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_capture_attempts_request_fingerprint_check CHECK ((request_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text))
);

ALTER TABLE ONLY public.paid_capture_attempts FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE paid_capture_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_capture_attempts IS 'Independent server-received paid-capture inputs. This table is the policy-v3 denominator; successful touch rows are never used as their own denominator.';


--
-- Name: paid_cohort_completeness_manifests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_cohort_completeness_manifests (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    evaluation_run_id uuid NOT NULL,
    cohort_kind text NOT NULL,
    window_start date NOT NULL,
    window_end date NOT NULL,
    source_not_before timestamp with time zone NOT NULL,
    capture_completed_at timestamp with time zone NOT NULL,
    linker_completed_at timestamp with time zone NOT NULL,
    contract_version integer NOT NULL,
    policy_version integer NOT NULL,
    capture_complete boolean NOT NULL,
    linker_complete boolean NOT NULL,
    capture_eligible_inputs bigint NOT NULL,
    captured_touches bigint NOT NULL,
    eligible_outcomes bigint NOT NULL,
    evaluated_outcomes bigint NOT NULL,
    linked_outcomes bigint NOT NULL,
    blocker_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_cohort_capture_completion_contract CHECK ((((capture_complete IS TRUE) AND (capture_eligible_inputs > 0) AND (captured_touches = capture_eligible_inputs)) OR (capture_complete IS FALSE))),
    CONSTRAINT paid_cohort_completeness_manifest_capture_eligible_inputs_check CHECK ((capture_eligible_inputs >= 0)),
    CONSTRAINT paid_cohort_completeness_manifests_captured_touches_check CHECK ((captured_touches >= 0)),
    CONSTRAINT paid_cohort_completeness_manifests_cohort_kind_check CHECK ((cohort_kind = ANY (ARRAY['recent_scale'::text, 'matured_cut'::text]))),
    CONSTRAINT paid_cohort_completeness_manifests_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_cohort_completeness_manifests_eligible_outcomes_check CHECK ((eligible_outcomes >= 0)),
    CONSTRAINT paid_cohort_completeness_manifests_evaluated_outcomes_check CHECK ((evaluated_outcomes >= 0)),
    CONSTRAINT paid_cohort_completeness_manifests_linked_outcomes_check CHECK ((linked_outcomes >= 0)),
    CONSTRAINT paid_cohort_completeness_manifests_policy_version_check CHECK ((policy_version = 1)),
    CONSTRAINT paid_cohort_completeness_time_order CHECK (((capture_completed_at >= source_not_before) AND (linker_completed_at >= source_not_before))),
    CONSTRAINT paid_cohort_completeness_window_order CHECK ((window_start <= window_end)),
    CONSTRAINT paid_cohort_linker_completion_contract CHECK (((linked_outcomes <= evaluated_outcomes) AND (evaluated_outcomes <= eligible_outcomes) AND (((linker_complete IS TRUE) AND (evaluated_outcomes = eligible_outcomes)) OR (linker_complete IS FALSE)))),
    CONSTRAINT paid_cohort_manifest_blocker_contract CHECK ((((capture_complete IS TRUE) AND (linker_complete IS TRUE) AND (cardinality(blocker_codes) = 0)) OR (((capture_complete IS FALSE) OR (linker_complete IS FALSE)) AND (cardinality(blocker_codes) > 0))))
);

ALTER TABLE ONLY public.paid_cohort_completeness_manifests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE paid_cohort_completeness_manifests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_cohort_completeness_manifests IS 'Policy-v3 manifests. Public paid-capture attempts are audit facts only, never an exhaustive capture denominator; capture completeness stays false until an independent enumerator exists.';


--
-- Name: paid_cohort_generations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_cohort_generations (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    evaluation_run_id uuid NOT NULL,
    cohort_kind text NOT NULL,
    window_start date NOT NULL,
    window_end date NOT NULL,
    as_of_date date NOT NULL,
    activation_id uuid,
    contract_version integer NOT NULL,
    policy_version integer NOT NULL,
    source_heads jsonb DEFAULT '{}'::jsonb NOT NULL,
    account_spend numeric,
    entity_spend numeric,
    landing_page_views bigint,
    captured_landing_views bigint,
    complete boolean NOT NULL,
    blocker_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    publication_fingerprint text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_cohort_complete_contract CHECK ((((complete IS TRUE) AND (cardinality(blocker_codes) = 0)) OR ((complete IS FALSE) AND (cardinality(blocker_codes) > 0)))),
    CONSTRAINT paid_cohort_generations_cohort_kind_check CHECK ((cohort_kind = ANY (ARRAY['recent_scale'::text, 'matured_cut'::text]))),
    CONSTRAINT paid_cohort_generations_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_cohort_generations_policy_version_check CHECK ((policy_version > 0)),
    CONSTRAINT paid_cohort_generations_publication_fingerprint_check CHECK ((publication_fingerprint ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT paid_cohort_known_policy_versions CHECK (((contract_version = 1) AND (policy_version = ANY (ARRAY[1, 2, 3])))),
    CONSTRAINT paid_cohort_window_order CHECK ((window_start <= window_end))
);


--
-- Name: TABLE paid_cohort_generations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_cohort_generations IS 'Immutable, direction-specific interaction-cohort manifests. Blocked evidence is persisted explicitly rather than represented as zero.';


--
-- Name: paid_cohort_policy_cutovers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_cohort_policy_cutovers (
    policy_version integer NOT NULL,
    activated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_cohort_policy_cutovers_policy_version_check CHECK ((policy_version = 3))
);


--
-- Name: TABLE paid_cohort_policy_cutovers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_cohort_policy_cutovers IS 'Deployment cutover marker. A fresh install ships it empty (v3 dormant); insert policy 3 only after all application readers and publishers use v3.';


--
-- Name: paid_cohort_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_cohort_units (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    generation_id uuid NOT NULL,
    entity_level public.entity_level NOT NULL,
    entity_id text NOT NULL,
    spend numeric,
    landing_page_views bigint,
    captured_touches bigint DEFAULT 0 NOT NULL,
    bookings bigint DEFAULT 0 NOT NULL,
    booked_value numeric DEFAULT 0 NOT NULL,
    complete boolean NOT NULL,
    blocker_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_cohort_unit_complete_contract CHECK ((((complete IS TRUE) AND (cardinality(blocker_codes) = 0)) OR ((complete IS FALSE) AND (cardinality(blocker_codes) > 0)))),
    CONSTRAINT paid_cohort_unit_counts CHECK (((captured_touches >= 0) AND (bookings >= 0) AND (booked_value >= (0)::numeric))),
    CONSTRAINT paid_cohort_units_entity_id_check CHECK (((length(btrim(entity_id)) >= 1) AND (length(btrim(entity_id)) <= 128)))
);


--
-- Name: paid_destination_token_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_destination_token_deliveries (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    browser_capture_id uuid NOT NULL,
    token_id uuid NOT NULL,
    delivery_status text NOT NULL,
    contract_version integer NOT NULL,
    delivered_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_destination_delivery_chronology CHECK ((created_at >= delivered_at)),
    CONSTRAINT paid_destination_token_deliveries_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_destination_token_deliveries_delivery_status_check CHECK ((delivery_status = 'scheduler_decorated'::text))
);

ALTER TABLE ONLY public.paid_destination_token_deliveries FORCE ROW LEVEL SECURITY;


