COMMENT ON TABLE public.paid_destination_token_deliveries IS 'Browser acknowledgements that a valid governed token was attached to at least one scheduler or checkout surface. A server response alone is not delivery proof.';


--
-- Name: paid_eligibility_surface_activations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_eligibility_surface_activations (
