    CONSTRAINT paid_eligibility_surface_activations_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_eligibility_surface_activations_source_ref_check CHECK (((length(btrim(source_ref)) >= 1) AND (length(btrim(source_ref)) <= 1024))),
    CONSTRAINT paid_eligibility_surface_activations_surface_check CHECK ((surface = ANY (ARRAY['capture_attempt'::text, 'scheduler_delivery'::text, 'outcome_link_evaluation'::text, 'collected_value_observation'::text])))
);

ALTER TABLE ONLY public.paid_eligibility_surface_activations FORCE ROW LEVEL SECURITY;


--
-- Name: paid_measurement_activations; Type: TABLE; Schema: public; Owner: -
