    CONSTRAINT paid_measurement_activations_policy_version_check CHECK ((policy_version = 1)),
    CONSTRAINT paid_measurement_activations_source_kind_check CHECK ((source_kind = ANY (ARRAY['controlled_journey'::text, 'owner_verified'::text]))),
    CONSTRAINT paid_measurement_activations_source_ref_check CHECK (((length(btrim(source_ref)) >= 1) AND (length(btrim(source_ref)) <= 1024)))
);


