    CONSTRAINT paid_outcome_eligibility_inputs_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_outcome_eligibility_inputs_input_fingerprint_check CHECK ((input_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT paid_outcome_input_chronology CHECK ((created_at >= received_at))
);

