--
-- Name: paid_outcome_link_evaluations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_outcome_link_evaluations (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    evaluation_fingerprint text NOT NULL,
    eligibility_input_id uuid NOT NULL,
    outcome_id uuid NOT NULL,
    outcome_created_at timestamp with time zone NOT NULL,
    paid_evidence_present boolean NOT NULL,
    token_id uuid,
    link_id uuid,
    last_touch_id uuid,
    last_interaction_at timestamp with time zone,
    evaluation_status text NOT NULL,
    reason_code text,
    collected_value numeric,
    cancelled boolean NOT NULL,
    contract_version integer NOT NULL,
    evaluated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_link_eval_chronology CHECK ((created_at >= evaluated_at)),
    CONSTRAINT paid_link_eval_shape CHECK ((((evaluation_status = 'linked'::text) AND (reason_code IS NULL) AND (link_id IS NOT NULL) AND (last_touch_id IS NOT NULL) AND (last_interaction_at IS NOT NULL)) OR ((evaluation_status <> 'linked'::text) AND (reason_code IS NOT NULL) AND (link_id IS NULL) AND (last_touch_id IS NULL) AND (last_interaction_at IS NULL)))),
    CONSTRAINT paid_link_eval_time_order CHECK (((last_interaction_at IS NULL) OR (last_interaction_at <= outcome_created_at))),
    CONSTRAINT paid_outcome_link_evaluations_collected_value_check CHECK (((collected_value IS NULL) OR (collected_value >= (0)::numeric))),
    CONSTRAINT paid_outcome_link_evaluations_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_outcome_link_evaluations_evaluation_fingerprint_check CHECK ((evaluation_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT paid_outcome_link_evaluations_evaluation_status_check CHECK ((evaluation_status = ANY (ARRAY['linked'::text, 'absent'::text, 'rejected'::text, 'error'::text, 'not_configured'::text]))),
    CONSTRAINT paid_outcome_link_evaluations_reason_code_check CHECK (((reason_code IS NULL) OR ((length(btrim(reason_code)) >= 1) AND (length(btrim(reason_code)) <= 128))))
);

ALTER TABLE ONLY public.paid_outcome_link_evaluations FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE paid_outcome_link_evaluations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.paid_outcome_link_evaluations IS 'One immutable fact per signed-webhook paid-link evaluation. Rejections and failures remain visible and block completeness.';


--
-- Name: paid_touch_observations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.paid_touch_observations (
    id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    browser_capture_id uuid NOT NULL,
    observed_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    source text NOT NULL,
    fbclid text,
    meta_campaign_id text,
    meta_adset_id text,
    meta_ad_id text,
    utm_source text NOT NULL,
    utm_medium text NOT NULL,
    utm_campaign text,
    utm_content text,
    utm_term text,
    landing_url text NOT NULL,
    referrer_url text,
    identity_complete boolean GENERATED ALWAYS AS (((meta_campaign_id IS NOT NULL) AND (meta_adset_id IS NOT NULL) AND (meta_ad_id IS NOT NULL))) STORED,
    contract_version integer NOT NULL,
    capture_fingerprint text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT paid_touch_observation_recording_chronology CHECK ((created_at >= observed_at)),
    CONSTRAINT paid_touch_observations_capture_fingerprint_check CHECK ((capture_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT paid_touch_observations_contract_version_check CHECK ((contract_version = 1)),
    CONSTRAINT paid_touch_observations_fbclid_check CHECK (((fbclid IS NULL) OR ((length(btrim(fbclid)) >= 1) AND (length(btrim(fbclid)) <= 1024)))),
    CONSTRAINT paid_touch_observations_landing_url_check CHECK (((landing_url ~ '^https://[^[:space:]]+$'::text) AND (length(landing_url) <= 2048))),
    CONSTRAINT paid_touch_observations_meta_ad_id_check CHECK (((meta_ad_id IS NULL) OR (meta_ad_id ~ '^[0-9]{1,32}$'::text))),
    CONSTRAINT paid_touch_observations_meta_adset_id_check CHECK (((meta_adset_id IS NULL) OR (meta_adset_id ~ '^[0-9]{1,32}$'::text))),
    CONSTRAINT paid_touch_observations_meta_campaign_id_check CHECK (((meta_campaign_id IS NULL) OR (meta_campaign_id ~ '^[0-9]{1,32}$'::text))),
    CONSTRAINT paid_touch_observations_referrer_url_check CHECK (((referrer_url IS NULL) OR ((referrer_url ~ '^https://[^[:space:]]+$'::text) AND (length(referrer_url) <= 2048)))),
    CONSTRAINT paid_touch_observations_source_check CHECK ((source = 'meta'::text)),
    CONSTRAINT paid_touch_observations_utm_campaign_check CHECK (((utm_campaign IS NULL) OR ((length(btrim(utm_campaign)) >= 1) AND (length(btrim(utm_campaign)) <= 512)))),
    CONSTRAINT paid_touch_observations_utm_content_check CHECK (((utm_content IS NULL) OR ((length(btrim(utm_content)) >= 1) AND (length(btrim(utm_content)) <= 512)))),
    CONSTRAINT paid_touch_observations_utm_medium_check CHECK ((utm_medium = 'paid_social'::text)),
    CONSTRAINT paid_touch_observations_utm_source_check CHECK ((utm_source = ANY (ARRAY['meta'::text, 'facebook'::text, 'instagram'::text]))),
    CONSTRAINT paid_touch_observations_utm_term_check CHECK (((utm_term IS NULL) OR ((length(btrim(utm_term)) >= 1) AND (length(btrim(utm_term)) <= 512))))
);


