    complete boolean NOT NULL,
    blocker_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    event_count integer NOT NULL,
    contract_version integer NOT NULL,
    publication_fingerprint text NOT NULL,
    imported_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT processor_settlement_batch_account_ref CHECK (((length(btrim(processor_account_ref)) >= 1) AND (length(btrim(processor_account_ref)) <= 256))),
    CONSTRAINT processor_settlement_batch_blocker_codes CHECK (((cardinality(blocker_codes) = 0) OR public.economics_code_array_valid(blocker_codes))),
    CONSTRAINT processor_settlement_batch_complete_contract CHECK (((complete AND (cardinality(blocker_codes) = 0)) OR ((NOT complete) AND (cardinality(blocker_codes) > 0) AND (event_count = 0)))),
    CONSTRAINT processor_settlement_batch_event_count CHECK (((event_count >= 0) AND (event_count <= 10000))),
    CONSTRAINT processor_settlement_batch_fingerprint CHECK ((publication_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT processor_settlement_batch_import_chronology CHECK ((imported_at >= window_end)),
    CONSTRAINT processor_settlement_batch_processor CHECK ((processor ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT processor_settlement_batch_source_head CHECK (((length(btrim(source_head)) >= 1) AND (length(btrim(source_head)) <= 1024))),
    CONSTRAINT processor_settlement_batch_window CHECK ((isfinite(window_start) AND isfinite(window_end) AND (window_end > window_start))),
    CONSTRAINT processor_settlement_batches_contract_version_check CHECK ((contract_version = 1))
);


