--
-- Name: processor_settlement_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.processor_settlement_events (
    id uuid NOT NULL,
    import_sequence bigint NOT NULL,
    ad_account_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    processor text NOT NULL,
    processor_account_ref text NOT NULL,
    processor_event_id text NOT NULL,
    processor_transaction_id text NOT NULL,
    event_kind text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    available_at timestamp with time zone NOT NULL,
    currency text NOT NULL,
    outcome_id uuid,
    collected_ex_tax_minor bigint DEFAULT 0 NOT NULL,
    refunds_ex_tax_minor bigint DEFAULT 0 NOT NULL,
    chargebacks_ex_tax_minor bigint DEFAULT 0 NOT NULL,
    recovered_chargebacks_ex_tax_minor bigint DEFAULT 0 NOT NULL,
    payment_fees_minor bigint DEFAULT 0 NOT NULL,
    tax_amount_minor bigint DEFAULT 0 NOT NULL,
    source_fingerprint text NOT NULL,
    contract_version integer NOT NULL,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT processor_settlement_event_account_ref CHECK (((length(btrim(processor_account_ref)) >= 1) AND (length(btrim(processor_account_ref)) <= 256))),
    CONSTRAINT processor_settlement_event_amounts CHECK (((collected_ex_tax_minor >= 0) AND (collected_ex_tax_minor <= '100000000000'::bigint) AND ((refunds_ex_tax_minor >= 0) AND (refunds_ex_tax_minor <= '100000000000'::bigint)) AND ((chargebacks_ex_tax_minor >= 0) AND (chargebacks_ex_tax_minor <= '100000000000'::bigint)) AND ((recovered_chargebacks_ex_tax_minor >= 0) AND (recovered_chargebacks_ex_tax_minor <= '100000000000'::bigint)) AND ((payment_fees_minor >= '-100000000000'::bigint) AND (payment_fees_minor <= '100000000000'::bigint)) AND ((tax_amount_minor >= 0) AND (tax_amount_minor <= '100000000000'::bigint)))),
    CONSTRAINT processor_settlement_event_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT processor_settlement_event_fingerprint CHECK ((source_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT processor_settlement_event_identity CHECK (((length(btrim(processor_event_id)) >= 1) AND (length(btrim(processor_event_id)) <= 512) AND ((length(btrim(processor_transaction_id)) >= 1) AND (length(btrim(processor_transaction_id)) <= 512)))),
    CONSTRAINT processor_settlement_event_import_chronology CHECK ((recorded_at >= available_at)),
    CONSTRAINT processor_settlement_event_kind CHECK ((event_kind = ANY (ARRAY['payment_settled'::text, 'refund_settled'::text, 'chargeback_settled'::text, 'chargeback_reversed'::text, 'fee_adjustment'::text]))),
    CONSTRAINT processor_settlement_event_kind_components CHECK ((((event_kind = 'payment_settled'::text) AND (collected_ex_tax_minor > 0) AND (refunds_ex_tax_minor = 0) AND (chargebacks_ex_tax_minor = 0) AND (recovered_chargebacks_ex_tax_minor = 0)) OR ((event_kind = 'refund_settled'::text) AND (collected_ex_tax_minor = 0) AND (refunds_ex_tax_minor > 0) AND (chargebacks_ex_tax_minor = 0) AND (recovered_chargebacks_ex_tax_minor = 0)) OR ((event_kind = 'chargeback_settled'::text) AND (collected_ex_tax_minor = 0) AND (refunds_ex_tax_minor = 0) AND (chargebacks_ex_tax_minor > 0) AND (recovered_chargebacks_ex_tax_minor = 0)) OR ((event_kind = 'chargeback_reversed'::text) AND (collected_ex_tax_minor = 0) AND (refunds_ex_tax_minor = 0) AND (chargebacks_ex_tax_minor = 0) AND (recovered_chargebacks_ex_tax_minor > 0)) OR ((event_kind = 'fee_adjustment'::text) AND (collected_ex_tax_minor = 0) AND (refunds_ex_tax_minor = 0) AND (chargebacks_ex_tax_minor = 0) AND (recovered_chargebacks_ex_tax_minor = 0) AND (payment_fees_minor <> 0)))),
    CONSTRAINT processor_settlement_event_processor CHECK ((processor ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT processor_settlement_event_time CHECK ((isfinite(occurred_at) AND isfinite(available_at) AND (available_at >= occurred_at))),
    CONSTRAINT processor_settlement_events_contract_version_check CHECK ((contract_version = 1))
);


