--
-- Name: recommendation_metric_claim_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recommendation_metric_claim_snapshots (
    claim_id text NOT NULL,
    ad_account_id uuid NOT NULL,
    source_flag_id uuid NOT NULL,
    source_flag_generation_id uuid NOT NULL,
    source_metric_key text NOT NULL,
    snapshot jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT recommendation_metric_claim_snapshot_complete CHECK (((jsonb_typeof(snapshot) = 'object'::text) AND (snapshot ?& ARRAY['claimId'::text, 'metricKey'::text, 'label'::text, 'value'::text, 'unit'::text, 'formula'::text, 'definitionVersion'::text, 'source'::text, 'entity'::text, 'attributionScope'::text, 'window'::text, 'comparison'::text, 'asOf'::text, 'availability'::text, 'coverage'::text, 'maturity'::text, 'freshness'::text, 'setupFingerprint'::text, 'authority'::text, 'measurementKind'::text, 'inputClaimIds'::text]) AND ((snapshot ->> 'claimId'::text) = claim_id) AND (jsonb_typeof((snapshot -> 'value'::text)) = 'number'::text) AND (jsonb_typeof((snapshot -> 'source'::text)) = 'object'::text) AND ((snapshot -> 'source'::text) ?& ARRAY['system'::text, 'role'::text, 'head'::text, 'evidencePlane'::text]) AND (jsonb_typeof((snapshot -> 'entity'::text)) = 'object'::text) AND ((snapshot -> 'entity'::text) ?& ARRAY['level'::text, 'id'::text]) AND (jsonb_typeof((snapshot -> 'window'::text)) = 'object'::text) AND ((snapshot -> 'window'::text) ?& ARRAY['start'::text, 'end'::text, 'basis'::text, 'timezone'::text]) AND (jsonb_typeof((snapshot -> 'freshness'::text)) = 'object'::text) AND ((snapshot -> 'freshness'::text) ?& ARRAY['state'::text, 'observedAt'::text, 'maxAgeHours'::text]) AND (jsonb_typeof((snapshot -> 'maturity'::text)) = 'object'::text) AND ((snapshot -> 'maturity'::text) ?& ARRAY['state'::text, 'matureThrough'::text]) AND (jsonb_typeof((snapshot -> 'authority'::text)) = 'object'::text) AND ((snapshot -> 'authority'::text) ?& ARRAY['state'::text, 'policyVersion'::text]) AND ((snapshot #>> '{freshness,state}'::text[]) = 'fresh'::text) AND (NULLIF(btrim((snapshot #>> '{freshness,observedAt}'::text[])), ''::text) IS NOT NULL) AND (NULLIF(btrim((snapshot #>> '{authority,policyVersion}'::text[])), ''::text) IS NOT NULL) AND ((snapshot #>> '{authority,state}'::text[]) = 'diagnostic'::text) AND ((snapshot #>> '{measurementKind}'::text[]) = ANY (ARRAY['measured'::text, 'modelled'::text, 'derived'::text])))),
    CONSTRAINT recommendation_metric_claim_snapshots_claim_id_check CHECK (((claim_id = btrim(claim_id)) AND ((length(claim_id) >= 1) AND (length(claim_id) <= 240)))),
    CONSTRAINT recommendation_metric_claim_snapshots_source_metric_key_check CHECK ((source_metric_key = ANY (ARRAY['cpa'::text, 'ctr'::text, 'frequency'::text, 'spend'::text, 'bookings'::text])))
);

ALTER TABLE ONLY public.recommendation_metric_claim_snapshots FORCE ROW LEVEL SECURITY;


