--
-- Name: v_business_outcomes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_business_outcomes AS
 SELECT o.id,
    o.ad_account_id,
    o.source_id,
    o.external_id,
    o.outcome_type,
    o.business_date,
    o.occurred_at,
    o.outcome_label,
    o.currency,
    o.gross_value,
    o.collected_value,
    o.status,
    o.origin,
    o.conversion_send_error,
    o.origin_observed_at,
    o.origin_observed_source,
        CASE
            WHEN (o.status = ANY (ARRAY['cancelled'::text, 'refunded'::text])) THEN 'cancelled'::text
            WHEN (COALESCE(o.gross_value, (0)::numeric) > (0)::numeric) THEN 'active_value_bearing'::text
            ELSE 'active_zero_value'::text
        END AS business_state,
        CASE
            WHEN (o.conversion_send_error = 'staff_created'::text) THEN 'staff_or_manual'::text
            WHEN (o.conversion_send_error = 'origin_unknown'::text) THEN 'origin_unknown'::text
            WHEN (o.origin = 'staff_or_manual'::text) THEN 'staff_or_manual'::text
            WHEN (o.origin_observed_at IS NOT NULL) THEN 'website'::text
            ELSE 'origin_unknown'::text
        END AS web_origin_state,
    o.conversion_sent_at,
    s.kind AS source_kind,
    s.enabled AS source_enabled,
    o.fbclid,
    o.utm_source,
    o.first_seen_at,
    o.fulfilment_at,
    o.email,
    o.raw
   FROM (public.outcomes o
     JOIN public.outcome_sources s ON (((s.id = o.source_id) AND (s.ad_account_id = o.ad_account_id))));


--
-- Name: VIEW v_business_outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_business_outcomes IS 'Canonical outcome classification on TWO axes. business_state: active_value_bearing (not cancelled AND gross_value > 0 — the only state contributing booked value) | active_zero_value (a REAL outcome that charged nothing: package, gift certificate, staff block, comp or test, which the ledger CANNOT distinguish, so it is never labelled test) | cancelled. web_origin_state: website (a by-id payload observed a client booking, so it SHOULD have produced a GA confirmation event) | staff_or_manual (no website session — its absence from GA is expected and must not block exact attribution) | origin_unknown (never established; it can be placed in neither group, so it BLOCKS exact attribution rather than being assumed either way). conversion_sent_at: when a server-side conversion send was RECORDED for this outcome — delivery evidence only, NOT proof Meta accepted it and NEVER an outcome, conversion or attribution claim. Booked value = sum(gross_value) over active_value_bearing — never a GA4 eventValue, and NOT the same figure as collected_value.';


--
-- Name: COLUMN v_business_outcomes.source_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.v_business_outcomes.source_kind IS 'outcome_sources.kind of the row''s source (csv, webhook, acuity). Source-specific semantics (an appointment id, a reconciliation window) apply only to rows of that kind.';


--
-- Name: COLUMN v_business_outcomes.source_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.v_business_outcomes.source_enabled IS 'outcome_sources.enabled. Readers count only enabled sources; a disabled source''s rows are kept but counted nowhere.';


--
-- Name: variable_cost_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.variable_cost_batches (
    id uuid NOT NULL,
    import_sequence bigint NOT NULL,
    ad_account_id uuid NOT NULL,
    economics_policy_id uuid NOT NULL,
    economics_policy_approval_id uuid NOT NULL,
    cost_source text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    source_head text NOT NULL,
    complete boolean NOT NULL,
    blocker_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    event_count integer NOT NULL,
    contract_version integer NOT NULL,
    publication_fingerprint text NOT NULL,
    imported_at timestamp with time zone NOT NULL,
    CONSTRAINT variable_cost_batch_blocker_codes CHECK (((cardinality(blocker_codes) = 0) OR public.economics_code_array_valid(blocker_codes))),
    CONSTRAINT variable_cost_batch_complete_contract CHECK (((complete AND (cardinality(blocker_codes) = 0)) OR ((NOT complete) AND (cardinality(blocker_codes) > 0) AND (event_count = 0)))),
    CONSTRAINT variable_cost_batch_event_count CHECK (((event_count >= 0) AND (event_count <= 10000))),
    CONSTRAINT variable_cost_batch_fingerprint CHECK ((publication_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT variable_cost_batch_import_chronology CHECK ((imported_at >= window_end)),
    CONSTRAINT variable_cost_batch_source CHECK ((cost_source ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT variable_cost_batch_source_head CHECK (((length(btrim(source_head)) >= 1) AND (length(btrim(source_head)) <= 1024))),
    CONSTRAINT variable_cost_batch_window CHECK ((isfinite(window_start) AND isfinite(window_end) AND (window_end > window_start))),
    CONSTRAINT variable_cost_batches_contract_version_check CHECK ((contract_version = 1))
);


--
-- Name: TABLE variable_cost_batches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.variable_cost_batches IS 'Immutable actual-cost source-window manifests. A complete batch proves only source coverage, not attribution, incrementality, or action authority.';


--
-- Name: variable_cost_batches_import_sequence_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.variable_cost_batches ALTER COLUMN import_sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.variable_cost_batches_import_sequence_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: variable_cost_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.variable_cost_events (
    id uuid NOT NULL,
    import_sequence bigint NOT NULL,
    ad_account_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    economics_policy_id uuid NOT NULL,
    cost_source text NOT NULL,
    source_event_id text NOT NULL,
    event_kind text NOT NULL,
    reverses_source_event_id text,
    occurred_at timestamp with time zone NOT NULL,
    available_at timestamp with time zone NOT NULL,
    currency text NOT NULL,
    outcome_id uuid NOT NULL,
    category text NOT NULL,
    amount_minor bigint NOT NULL,
    source_fingerprint text NOT NULL,
    contract_version integer NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT variable_cost_event_amount CHECK (((amount_minor >= 1) AND (amount_minor <= '100000000000'::bigint))),
    CONSTRAINT variable_cost_event_category CHECK ((category ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT variable_cost_event_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT variable_cost_event_fingerprint CHECK ((source_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT variable_cost_event_identity CHECK (((length(btrim(source_event_id)) >= 1) AND (length(btrim(source_event_id)) <= 512))),
    CONSTRAINT variable_cost_event_import_chronology CHECK ((recorded_at >= available_at)),
    CONSTRAINT variable_cost_event_kind CHECK ((event_kind = ANY (ARRAY['cost_incurred'::text, 'cost_reversed'::text]))),
    CONSTRAINT variable_cost_event_reversal_shape CHECK ((((event_kind = 'cost_incurred'::text) AND (reverses_source_event_id IS NULL)) OR ((event_kind = 'cost_reversed'::text) AND (reverses_source_event_id IS NOT NULL)))),
    CONSTRAINT variable_cost_event_source CHECK ((cost_source ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT variable_cost_event_time CHECK ((isfinite(occurred_at) AND isfinite(available_at) AND (available_at >= occurred_at))),
    CONSTRAINT variable_cost_events_contract_version_check CHECK ((contract_version = 1))
);


--
-- Name: TABLE variable_cost_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.variable_cost_events IS 'Immutable outcome-linked actual variable costs and bounded reversals in integer minor units of the row''s currency. Gross-margin estimates and fixed overhead are forbidden substitutes.';


--
-- Name: weekly_executive_delivery_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_executive_delivery_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    provider text NOT NULL,
    recipient text NOT NULL,
    payload_fingerprint text NOT NULL,
    message_id text NOT NULL,
    status text DEFAULT 'claimed'::text NOT NULL,
    provider_message_id text,
    claimed_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT weekly_executive_delivery_attempt_state_valid CHECK ((((status = 'claimed'::text) AND (completed_at IS NULL) AND (provider_message_id IS NULL)) OR ((status = ANY (ARRAY['sent'::text, 'failed'::text, 'ambiguous'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT weekly_executive_delivery_attempts_message_id_check CHECK (((message_id = btrim(message_id)) AND ((length(message_id) >= 3) AND (length(message_id) <= 320)) AND (message_id !~ '[[:cntrl:]]'::text))),
    CONSTRAINT weekly_executive_delivery_attempts_payload_fingerprint_check CHECK ((payload_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT weekly_executive_delivery_attempts_provider_check CHECK ((provider = ANY (ARRAY['gmail_smtp'::text, 'resend'::text]))),
    CONSTRAINT weekly_executive_delivery_attempts_provider_message_id_check CHECK (((provider_message_id IS NULL) OR ((provider_message_id = btrim(provider_message_id)) AND ((length(provider_message_id) >= 1) AND (length(provider_message_id) <= 512)) AND (provider_message_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT weekly_executive_delivery_attempts_recipient_check CHECK (((recipient = btrim(recipient)) AND ((length(recipient) >= 3) AND (length(recipient) <= 320)) AND (recipient ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text) AND (recipient !~ '[<>,;]'::text))),
    CONSTRAINT weekly_executive_delivery_attempts_status_check CHECK ((status = ANY (ARRAY['claimed'::text, 'sent'::text, 'failed'::text, 'ambiguous'::text])))
);


--
-- Name: TABLE weekly_executive_delivery_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.weekly_executive_delivery_attempts IS 'Append-only one-shot email claims; any attempt is terminal for a committed weekly report and recipient.';


--
-- Name: weekly_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    week_start date NOT NULL,
    week_end date NOT NULL,
    summary_text text,
    full_report_md text,
    report_json jsonb,
    total_spend numeric DEFAULT 0,
    total_leads bigint DEFAULT 0,
    total_bookings bigint DEFAULT 0,
    avg_cpl numeric,
    avg_cpb numeric,
    ga4_bookings bigint DEFAULT 0,
    ga4_revenue numeric DEFAULT 0,
    prev_total_spend numeric,
    prev_total_bookings bigint,
    model_used text,
    generated_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    business_outcomes integer,
    business_revenue numeric,
    money_basis_version integer NOT NULL,
    business_revenue_basis text NOT NULL,
    outcome_source_available boolean,
    business_revenue_complete boolean,
    collected_value_lower_bound numeric,
    collected_value_covered_outcomes integer,
    collected_value_total_outcomes integer,
    executive_evidence_generation_id uuid,
    CONSTRAINT weekly_reports_money_basis_contract CHECK ((((money_basis_version = 0) AND (business_revenue_basis = 'legacy_unversioned'::text) AND (outcome_source_available IS NULL) AND (business_revenue_complete IS NULL) AND (collected_value_lower_bound IS NULL) AND (collected_value_covered_outcomes IS NULL) AND (collected_value_total_outcomes IS NULL)) OR ((money_basis_version = 1) AND (business_revenue_basis = 'outcome_collected_value'::text) AND (outcome_source_available IS NOT NULL) AND (((NOT outcome_source_available) AND (business_revenue_complete IS NULL) AND (collected_value_lower_bound IS NULL) AND (collected_value_covered_outcomes IS NULL) AND (collected_value_total_outcomes IS NULL) AND (business_revenue IS NULL)) OR (outcome_source_available AND (business_revenue_complete IS NOT NULL) AND (collected_value_lower_bound >= (0)::numeric) AND (collected_value_covered_outcomes >= 0) AND (collected_value_total_outcomes >= collected_value_covered_outcomes) AND ((business_revenue_complete AND (collected_value_covered_outcomes = collected_value_total_outcomes) AND (business_revenue IS NOT NULL) AND (business_revenue = collected_value_lower_bound)) OR ((NOT business_revenue_complete) AND (collected_value_covered_outcomes < collected_value_total_outcomes) AND (business_revenue IS NULL))))))))
);


--
-- Name: COLUMN weekly_reports.business_outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.weekly_reports.business_outcomes IS 'Canonical outcomes from the enabled outcome sources (non-cancelled) for the week, by account-timezone outcome date. Business truth; total_bookings stays the Meta-attributed estimate and ga4_bookings the GA4 lens.';


--
-- Name: COLUMN weekly_reports.business_revenue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.weekly_reports.business_revenue IS 'Versioned checkout revenue. For money_basis_version=1 this equals complete outcome collected_value (Acuity: amount_paid) over active outcomes; NULL when coverage is incomplete. Legacy v0 rows may contain scheduled booked value.';


--
-- Name: COLUMN weekly_reports.collected_value_lower_bound; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.weekly_reports.collected_value_lower_bound IS 'Observed sum of non-null outcome collected values (Acuity: amount_paid). Diagnostic lower bound only when revenue coverage is incomplete.';


--
-- Name: COLUMN weekly_reports.executive_evidence_generation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.weekly_reports.executive_evidence_generation_id IS 'Exact immutable ExecutiveEvidenceSnapshotV1 used by a current WeeklyDigestV1.';


