--
-- Name: DEFAULT PRIVILEGES FOR TABLES; Type: DEFAULT ACL; Schema: public; Owner: -
--



--
-- ADR-062: campaign plans. A plan is drafted in Maxx, validated server-side, submitted as an
-- owner-initiated create_campaign_paused change request and, after approval and only with write
-- mode on, created in Meta with every object PAUSED. Versions are immutable; the status moves only
-- along governed edges; created Meta ids are recorded per object so a retry resumes, never duplicates.
--

CREATE TABLE public.campaign_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ad_account_id uuid NOT NULL,
    title text NOT NULL,
    brief jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    latest_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT campaign_plans_title_check CHECK (((length(btrim(title)) >= 1) AND (length(title) <= 200))),
    CONSTRAINT campaign_plans_brief_object CHECK ((jsonb_typeof(brief) = 'object'::text))
);

COMMENT ON TABLE public.campaign_plans IS 'ADR-062: a campaign plan drafted in Maxx (identity, title and the owner brief). Its content lives in immutable campaign_plan_versions. Service role only.';

CREATE TABLE public.campaign_plan_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    version integer NOT NULL,
    spec jsonb NOT NULL,
    spec_hash text NOT NULL,
    currency text NOT NULL,
    total_daily_budget_minor bigint NOT NULL,
    validation jsonb DEFAULT '[]'::jsonb NOT NULL,
    readiness jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    source text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    status_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT campaign_plan_versions_version_check CHECK ((version >= 1)),
    CONSTRAINT campaign_plan_versions_spec_object CHECK ((jsonb_typeof(spec) = 'object'::text)),
    CONSTRAINT campaign_plan_versions_hash_check CHECK ((spec_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT campaign_plan_versions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT campaign_plan_versions_budget_check CHECK ((total_daily_budget_minor > 0)),
    CONSTRAINT campaign_plan_versions_json_arrays CHECK (((jsonb_typeof(validation) = 'array'::text) AND (jsonb_typeof(readiness) = 'array'::text) AND (jsonb_typeof(notes) = 'array'::text))),
    CONSTRAINT campaign_plan_versions_source_check CHECK ((source = ANY (ARRAY['template'::text, 'ai'::text, 'owner_edit'::text]))),
    CONSTRAINT campaign_plan_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'creating'::text, 'created_paused'::text, 'failed'::text, 'superseded'::text, 'archived'::text])))
);

COMMENT ON TABLE public.campaign_plan_versions IS 'ADR-062: one immutable version of a campaign plan (the server-validated spec, its hash, validation findings and launch readiness). Content is frozen after insert; status moves only along governed edges. An edit is a new version. Service role only.';

CREATE TABLE public.campaign_plan_objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_version_id uuid NOT NULL,
    ad_account_id uuid NOT NULL,
    change_request_id uuid NOT NULL,
    object_kind text NOT NULL,
    local_key text NOT NULL,
    marker text NOT NULL,
    meta_id text,
    parent_meta_id text,
    state text DEFAULT 'pending'::text NOT NULL,
    simulated boolean DEFAULT false NOT NULL,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    origin text DEFAULT 'created'::text NOT NULL,
    CONSTRAINT campaign_plan_objects_origin_check CHECK ((origin = ANY (ARRAY['created'::text, 'found'::text]))),
    CONSTRAINT campaign_plan_objects_kind_check CHECK ((object_kind = ANY (ARRAY['campaign'::text, 'adset'::text, 'creative'::text, 'ad'::text]))),
    CONSTRAINT campaign_plan_objects_key_check CHECK ((local_key ~ '^[a-z0-9:_-]{1,80}$'::text)),
    CONSTRAINT campaign_plan_objects_marker_check CHECK ((marker ~ '^[a-z0-9-]{1,40}$'::text)),
    CONSTRAINT campaign_plan_objects_meta_id_check CHECK (((meta_id IS NULL) OR (meta_id ~ '^[0-9]{1,32}$'::text) OR (meta_id ~ '^demo-[a-z0-9-]{1,60}$'::text))),
    CONSTRAINT campaign_plan_objects_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'created'::text, 'verified'::text, 'unverified'::text, 'archived'::text, 'archive_failed'::text]))),
    CONSTRAINT campaign_plan_objects_error_check CHECK (((error_code IS NULL) OR (error_code ~ '^[A-Z0-9_]{1,64}$'::text)))
);

COMMENT ON TABLE public.campaign_plan_objects IS 'ADR-062: the Meta objects a create_campaign_paused request created (or is creating), one row per plan key, with the stable marker embedded in the object name. The marker is bound to the one creation request (sha256 of its plan version and change request ids), so a retry finds only an object this request made. A retry resumes from these rows instead of creating a duplicate. The Meta id is frozen once recorded and held by at most one row per account. Service role only.';

ALTER TABLE ONLY public.campaign_plans ADD CONSTRAINT campaign_plans_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.campaign_plan_versions ADD CONSTRAINT campaign_plan_versions_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.campaign_plan_versions ADD CONSTRAINT campaign_plan_versions_plan_version_key UNIQUE (plan_id, version);
ALTER TABLE ONLY public.campaign_plan_objects ADD CONSTRAINT campaign_plan_objects_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.campaign_plan_objects ADD CONSTRAINT campaign_plan_objects_version_key UNIQUE (plan_version_id, local_key);
ALTER TABLE ONLY public.campaign_plans ADD CONSTRAINT campaign_plans_ad_account_id_fkey FOREIGN KEY (ad_account_id) REFERENCES public.ad_accounts(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.campaign_plan_versions ADD CONSTRAINT campaign_plan_versions_plan_id_fkey FOREIGN KEY (plan_id) REFERENCES public.campaign_plans(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.campaign_plan_versions ADD CONSTRAINT campaign_plan_versions_ad_account_id_fkey FOREIGN KEY (ad_account_id) REFERENCES public.ad_accounts(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.campaign_plan_objects ADD CONSTRAINT campaign_plan_objects_version_fkey FOREIGN KEY (plan_version_id) REFERENCES public.campaign_plan_versions(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.campaign_plan_objects ADD CONSTRAINT campaign_plan_objects_ad_account_id_fkey FOREIGN KEY (ad_account_id) REFERENCES public.ad_accounts(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.campaign_plan_objects ADD CONSTRAINT campaign_plan_objects_change_request_fkey FOREIGN KEY (change_request_id) REFERENCES public.change_requests(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.change_requests ADD CONSTRAINT change_requests_campaign_plan_version_fkey FOREIGN KEY (campaign_plan_version_id) REFERENCES public.campaign_plan_versions(id) ON DELETE RESTRICT;

CREATE INDEX idx_campaign_plans_account ON public.campaign_plans USING btree (ad_account_id, created_at DESC);
CREATE INDEX idx_campaign_plan_versions_plan ON public.campaign_plan_versions USING btree (plan_id, version DESC);
CREATE INDEX idx_campaign_plan_objects_request ON public.campaign_plan_objects USING btree (change_request_id);
-- A Meta object belongs to at most one plan object row in an account: no request can adopt another's.
CREATE UNIQUE INDEX uq_campaign_plan_objects_meta_id ON public.campaign_plan_objects USING btree (ad_account_id, meta_id) WHERE (meta_id IS NOT NULL);
-- One live creation request per plan version (its rollback is the separate rollback_of row).
CREATE UNIQUE INDEX uq_change_requests_campaign_plan_version ON public.change_requests USING btree (campaign_plan_version_id) WHERE ((campaign_plan_version_id IS NOT NULL) AND (rollback_of IS NULL));

--
-- Name: campaign_plan_versions_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_plan_versions_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_plan_account uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT ad_account_id INTO v_plan_account FROM public.campaign_plans WHERE id = NEW.plan_id;
    IF v_plan_account IS DISTINCT FROM NEW.ad_account_id THEN
      RAISE EXCEPTION 'campaign_plan_account_mismatch';
    END IF;
    IF NEW.status <> 'draft' THEN RAISE EXCEPTION 'campaign_plan_version_must_start_as_draft'; END IF;
    NEW.status_changed_at := now();
    RETURN NEW;
  END IF;

  IF (NEW.plan_id, NEW.ad_account_id, NEW.version, NEW.spec, NEW.spec_hash, NEW.currency,
      NEW.total_daily_budget_minor, NEW.validation, NEW.readiness, NEW.notes, NEW.source,
      NEW.created_by_user_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.plan_id, OLD.ad_account_id, OLD.version, OLD.spec, OLD.spec_hash, OLD.currency,
      OLD.total_daily_budget_minor, OLD.validation, OLD.readiness, OLD.notes, OLD.source,
      OLD.created_by_user_id, OLD.created_at) THEN
    RAISE EXCEPTION 'campaign_plan_version_content_is_immutable';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status = 'draft' AND NEW.status IN ('pending_approval', 'superseded'))
      OR (OLD.status = 'pending_approval' AND NEW.status IN ('approved', 'rejected'))
      OR (OLD.status = 'approved' AND NEW.status = 'creating')
      OR (OLD.status = 'creating' AND NEW.status IN ('created_paused', 'failed'))
      OR (OLD.status = 'failed' AND NEW.status IN ('creating', 'archived'))
      OR (OLD.status = 'created_paused' AND NEW.status = 'archived')
    ) THEN
      RAISE EXCEPTION 'campaign_plan_version_illegal_transition % -> %', OLD.status, NEW.status;
    END IF;
    NEW.status_changed_at := now();
  ELSE
    NEW.status_changed_at := OLD.status_changed_at;
  END IF;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.campaign_plan_versions_guard() IS 'ADR-062: a version starts as draft in its plan''s account, its content is frozen, and its status moves only draft -> pending_approval|superseded, pending_approval -> approved|rejected, approved -> creating, creating -> created_paused|failed, failed -> creating|archived, created_paused -> archived.';

CREATE TRIGGER trg_campaign_plan_versions_guard BEFORE INSERT OR UPDATE ON public.campaign_plan_versions FOR EACH ROW EXECUTE FUNCTION public.campaign_plan_versions_guard();

--
-- Name: campaign_plan_objects_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_plan_objects_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_version_account uuid;
  v_request_version uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT ad_account_id INTO v_version_account FROM public.campaign_plan_versions WHERE id = NEW.plan_version_id;
    SELECT campaign_plan_version_id INTO v_request_version FROM public.change_requests WHERE id = NEW.change_request_id;
    IF v_version_account IS DISTINCT FROM NEW.ad_account_id THEN
      RAISE EXCEPTION 'campaign_plan_object_account_mismatch';
    END IF;
    IF v_request_version IS DISTINCT FROM NEW.plan_version_id THEN
      RAISE EXCEPTION 'campaign_plan_object_request_mismatch';
    END IF;
    -- The marker is bound to this one creation request (security review H1): the same expression the
    -- application derives (markerSeed/objectMarker), so a row cannot carry another request's marker.
    IF NEW.marker IS DISTINCT FROM 'mx' || left(encode(sha256(convert_to(NEW.plan_version_id::text || ':' || NEW.change_request_id::text, 'UTF8')), 'hex'), 12)
                                    || '-' || replace(NEW.local_key, ':', '-') THEN
      RAISE EXCEPTION 'campaign_plan_object_marker_not_bound_to_request';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.plan_version_id, NEW.ad_account_id, NEW.change_request_id, NEW.object_kind, NEW.local_key, NEW.marker, NEW.simulated, NEW.created_at)
     IS DISTINCT FROM
     (OLD.plan_version_id, OLD.ad_account_id, OLD.change_request_id, OLD.object_kind, OLD.local_key, OLD.marker, OLD.simulated, OLD.created_at)
     OR (OLD.meta_id IS NOT NULL AND NEW.meta_id IS DISTINCT FROM OLD.meta_id)
     OR (OLD.meta_id IS NOT NULL AND NEW.origin IS DISTINCT FROM OLD.origin)
     OR (OLD.parent_meta_id IS NOT NULL AND NEW.parent_meta_id IS DISTINCT FROM OLD.parent_meta_id) THEN
    RAISE EXCEPTION 'campaign_plan_object_identity_is_immutable';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.campaign_plan_objects_guard() IS 'ADR-062: an object row belongs to its version''s account and its creation request, under a marker bound to that request; its identity, and its Meta id and origin once recorded, never change.';

CREATE TRIGGER trg_campaign_plan_objects_guard BEFORE INSERT OR UPDATE ON public.campaign_plan_objects FOR EACH ROW EXECUTE FUNCTION public.campaign_plan_objects_guard();

--
-- Name: enforce_campaign_plan_change_request(public.change_requests, public.change_requests, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_plan_change_request(p_new public.change_requests, p_old public.change_requests, p_op text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_version public.campaign_plan_versions;
  v_original public.change_requests;
  v_expected jsonb;
BEGIN
  IF p_new.campaign_plan_version_id IS NULL THEN RAISE EXCEPTION 'campaign_plan_version_required'; END IF;
  IF p_new.initiated_by <> 'owner' OR p_new.requested_by_user_id IS NULL OR p_new.action_decision_id IS NOT NULL THEN
    RAISE EXCEPTION 'campaign_plan_change_request_must_be_owner_initiated';
  END IF;
  IF p_op = 'UPDATE' THEN
    IF p_new.campaign_plan_version_id IS DISTINCT FROM p_old.campaign_plan_version_id
       OR (p_new.initiated_by, p_new.requested_by_user_id, p_new.rollback_of, p_new.step_override, p_new.action_decision_id)
          IS DISTINCT FROM (p_old.initiated_by, p_old.requested_by_user_id, p_old.rollback_of, p_old.step_override, p_old.action_decision_id) THEN
      RAISE EXCEPTION 'campaign_plan_change_request_lineage_is_immutable';
    END IF;
    IF (p_new.ad_account_id, p_new.action_type, p_new.entity_level, p_new.meta_entity_id,
        p_new.params, p_new.before_state, p_new.preview, p_new.idempotency_key)
       IS DISTINCT FROM
       (p_old.ad_account_id, p_old.action_type, p_old.entity_level, p_old.meta_entity_id,
        p_old.params, p_old.before_state, p_old.preview, p_old.idempotency_key) THEN
      RAISE EXCEPTION 'change_request_authorized_payload_is_immutable';
    END IF;
    RETURN;
  END IF;

  SELECT * INTO v_version FROM public.campaign_plan_versions WHERE id = p_new.campaign_plan_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_plan_version_not_found'; END IF;
  IF v_version.ad_account_id IS DISTINCT FROM p_new.ad_account_id THEN
    RAISE EXCEPTION 'campaign_plan_version_account_mismatch';
  END IF;
  IF p_new.entity_level <> 'account' THEN RAISE EXCEPTION 'campaign_plan_change_request_level_invalid'; END IF;

  v_expected := jsonb_build_object('plan_version_id', v_version.id::text, 'spec_hash', v_version.spec_hash);
  IF p_new.action_type = 'create_campaign_paused' THEN
    IF p_new.rollback_of IS NOT NULL THEN RAISE EXCEPTION 'campaign_plan_create_cannot_be_a_rollback'; END IF;
    IF v_version.status <> 'pending_approval' THEN RAISE EXCEPTION 'campaign_plan_version_not_submitted'; END IF;
  ELSIF p_new.action_type = 'archive_campaign_plan_objects' THEN
    SELECT * INTO v_original FROM public.change_requests WHERE id = p_new.rollback_of;
    IF NOT FOUND
       OR v_original.ad_account_id IS DISTINCT FROM p_new.ad_account_id
       OR v_original.campaign_plan_version_id IS DISTINCT FROM p_new.campaign_plan_version_id
       OR v_original.action_type <> 'create_campaign_paused'
       OR v_original.rollback_of IS NOT NULL
       OR v_original.status::text NOT IN ('executed', 'failed') THEN
      RAISE EXCEPTION 'campaign_plan_rollback_original_invalid';
    END IF;
    IF jsonb_typeof(p_new.params->'meta_ids') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_new.params->'meta_ids') NOT BETWEEN 1 AND 300
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_new.params->'meta_ids') e
                   WHERE jsonb_typeof(e) <> 'string' OR NOT ((e #>> '{}') ~ '^([0-9]{1,32}|demo-[a-z0-9-]{1,60})$')) THEN
      RAISE EXCEPTION 'campaign_plan_rollback_meta_ids_invalid';
    END IF;
    v_expected := v_expected || jsonb_build_object('meta_ids', p_new.params->'meta_ids');
  ELSE
    RAISE EXCEPTION 'change_request_action_type_not_governed';
  END IF;
  IF p_new.params IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'campaign_plan_change_request_params_mismatch';
  END IF;
END;
$$;

COMMENT ON FUNCTION public.enforce_campaign_plan_change_request(p_new public.change_requests, p_old public.change_requests, p_op text) IS 'ADR-062: the change-request rules for a campaign plan: owner-initiated, never an ActionDecision, account-level, params exactly the version id and spec hash (plus the Meta ids for an archive rollback of an executed or failed creation), a create only for a submitted version, and lineage and payload frozen after insert.';

--
-- Name: create_campaign_plan_version(uuid, uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_campaign_plan_version(p_plan_id uuid, p_ad_account_id uuid, p_owner_user_id uuid, p_title text, p_brief jsonb, p_version jsonb) RETURNS public.campaign_plan_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_plan public.campaign_plans;
  v_row public.campaign_plan_versions;
  v_allowed_keys text[] := ARRAY['spec','spec_hash','currency','total_daily_budget_minor','validation','readiness','notes','source'];
BEGIN
  IF p_owner_user_id IS NULL THEN RAISE EXCEPTION 'campaign_plan_requires_owner_identity'; END IF;
  IF jsonb_typeof(p_version) IS DISTINCT FROM 'object' OR (p_version - v_allowed_keys) <> '{}'::jsonb THEN
    RAISE EXCEPTION 'campaign_plan_version_payload_invalid';
  END IF;
  IF p_plan_id IS NULL THEN
    INSERT INTO public.campaign_plans (ad_account_id, title, brief, created_by_user_id)
    VALUES (p_ad_account_id, p_title, COALESCE(p_brief, '{}'::jsonb), p_owner_user_id)
    RETURNING * INTO v_plan;
  ELSE
    SELECT * INTO v_plan FROM public.campaign_plans WHERE id = p_plan_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'campaign_plan_not_found'; END IF;
    IF v_plan.ad_account_id IS DISTINCT FROM p_ad_account_id THEN RAISE EXCEPTION 'campaign_plan_account_mismatch'; END IF;
    IF EXISTS (SELECT 1 FROM public.campaign_plan_versions
                WHERE plan_id = v_plan.id AND status IN ('pending_approval', 'approved', 'creating')) THEN
      RAISE EXCEPTION 'campaign_plan_has_version_in_flight';
    END IF;
    UPDATE public.campaign_plan_versions SET status = 'superseded' WHERE plan_id = v_plan.id AND status = 'draft';
  END IF;
  UPDATE public.campaign_plans SET latest_version = latest_version + 1 WHERE id = v_plan.id RETURNING * INTO v_plan;
  INSERT INTO public.campaign_plan_versions (
    plan_id, ad_account_id, version, spec, spec_hash, currency, total_daily_budget_minor,
    validation, readiness, notes, source, created_by_user_id)
  VALUES (
    v_plan.id, p_ad_account_id, v_plan.latest_version, p_version->'spec', p_version->>'spec_hash',
    p_version->>'currency', (p_version->>'total_daily_budget_minor')::bigint,
    COALESCE(p_version->'validation', '[]'::jsonb), COALESCE(p_version->'readiness', '[]'::jsonb),
    COALESCE(p_version->'notes', '[]'::jsonb), p_version->>'source', p_owner_user_id)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;

COMMENT ON FUNCTION public.create_campaign_plan_version(p_plan_id uuid, p_ad_account_id uuid, p_owner_user_id uuid, p_title text, p_brief jsonb, p_version jsonb) IS 'ADR-062: create a plan (p_plan_id NULL) or its next version, superseding the previous draft. Refused while a version is pending approval, approved or being created. Service role only; called after the owner gate with a server-validated spec.';

--
-- Name: create_campaign_plan_change_request(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_campaign_plan_change_request(p_plan_version_id uuid, p_owner_user_id uuid, p_request jsonb) RETURNS public.change_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_version public.campaign_plan_versions;
  v_existing public.change_requests;
  v_original public.change_requests;
  v_row public.change_requests;
  v_account_meta_id text;
  v_action text := p_request->>'action_type';
  v_rollback_of uuid := NULLIF(p_request->>'rollback_of', '')::uuid;
  v_params jsonb;
  v_allowed_keys text[] := ARRAY[
    'ad_account_id','action_type','before_state','preview','reason','risk_level','rollback_plan',
    'idempotency_key','requested_by','evidence','data_source','step_override','rollback_of','meta_ids'];
BEGIN
  IF p_owner_user_id IS NULL THEN RAISE EXCEPTION 'campaign_plan_change_request_requires_owner_identity'; END IF;
  IF jsonb_typeof(p_request) IS DISTINCT FROM 'object' OR (p_request - v_allowed_keys) <> '{}'::jsonb THEN
    RAISE EXCEPTION 'change_request_payload_invalid_or_contains_unknown_keys';
  END IF;
  SELECT * INTO v_version FROM public.campaign_plan_versions WHERE id = p_plan_version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_plan_version_not_found'; END IF;
  IF v_version.ad_account_id IS DISTINCT FROM (p_request->>'ad_account_id')::uuid THEN
    RAISE EXCEPTION 'campaign_plan_version_account_mismatch';
  END IF;
  SELECT account_id INTO v_account_meta_id FROM public.ad_accounts WHERE id = v_version.ad_account_id;
  v_params := jsonb_build_object('plan_version_id', v_version.id::text, 'spec_hash', v_version.spec_hash);

  IF v_action = 'create_campaign_paused' THEN
    IF v_rollback_of IS NOT NULL THEN RAISE EXCEPTION 'campaign_plan_create_cannot_be_a_rollback'; END IF;
    SELECT * INTO v_existing FROM public.change_requests
     WHERE campaign_plan_version_id = v_version.id AND rollback_of IS NULL;
    IF FOUND THEN RETURN v_existing; END IF;
    IF v_version.status <> 'draft' THEN RAISE EXCEPTION 'campaign_plan_version_not_draft'; END IF;
    UPDATE public.campaign_plan_versions SET status = 'pending_approval' WHERE id = v_version.id;
  ELSIF v_action = 'archive_campaign_plan_objects' THEN
    SELECT * INTO v_original FROM public.change_requests WHERE id = v_rollback_of FOR UPDATE;
    IF NOT FOUND OR v_original.campaign_plan_version_id IS DISTINCT FROM v_version.id
       OR v_original.action_type <> 'create_campaign_paused' OR v_original.status::text NOT IN ('executed', 'failed') THEN
      RAISE EXCEPTION 'campaign_plan_rollback_original_invalid';
    END IF;
    SELECT * INTO v_existing FROM public.change_requests
     WHERE rollback_of = v_rollback_of AND status::text IN ('pending', 'approved', 'executed');
    IF FOUND THEN RETURN v_existing; END IF;
    v_params := v_params || jsonb_build_object('meta_ids', p_request->'meta_ids');
  ELSE
    RAISE EXCEPTION 'change_request_action_type_not_governed';
  END IF;

  INSERT INTO public.change_requests (
    ad_account_id, action_type, entity_level, meta_entity_id, params, before_state, preview, reason,
    risk_level, rollback_plan, idempotency_key, status, requested_by, evidence, data_source,
    initiated_by, requested_by_user_id, rollback_of, step_override, campaign_plan_version_id)
  VALUES (
    v_version.ad_account_id, v_action, 'account', COALESCE(v_account_meta_id, ''), v_params,
    NULLIF(p_request->'before_state', 'null'::jsonb), p_request->>'preview', p_request->>'reason',
    p_request->>'risk_level', p_request->>'rollback_plan', p_request->>'idempotency_key', 'pending',
    COALESCE(NULLIF(p_request->>'requested_by', ''), 'owner'), p_request->>'evidence', p_request->>'data_source',
    'owner', p_owner_user_id, v_rollback_of, COALESCE((p_request->>'step_override')::boolean, false), v_version.id)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;

COMMENT ON FUNCTION public.create_campaign_plan_change_request(p_plan_version_id uuid, p_owner_user_id uuid, p_request jsonb) IS 'ADR-062: submit a draft plan version as an owner-initiated create_campaign_paused change request (or propose archiving the objects an executed or failed creation made). The database derives the params from the version. Idempotent per version, and per original for a rollback. Service role only.';

ALTER TABLE public.campaign_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campaign_plan_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campaign_plan_objects ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaign_plans_service_all ON public.campaign_plans TO service_role USING (true) WITH CHECK (true);
CREATE POLICY campaign_plan_versions_service_all ON public.campaign_plan_versions TO service_role USING (true) WITH CHECK (true);
CREATE POLICY campaign_plan_objects_service_all ON public.campaign_plan_objects TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON TABLE public.campaign_plans FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.campaign_plan_versions FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.campaign_plan_objects FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.campaign_plans TO service_role;
GRANT ALL ON TABLE public.campaign_plan_versions TO service_role;
GRANT ALL ON TABLE public.campaign_plan_objects TO service_role;
REVOKE ALL ON FUNCTION public.campaign_plan_versions_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.campaign_plan_objects_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.enforce_campaign_plan_change_request(p_new public.change_requests, p_old public.change_requests, p_op text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.create_campaign_plan_version(p_plan_id uuid, p_ad_account_id uuid, p_owner_user_id uuid, p_title text, p_brief jsonb, p_version jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.create_campaign_plan_change_request(p_plan_version_id uuid, p_owner_user_id uuid, p_request jsonb) FROM PUBLIC;
GRANT ALL ON FUNCTION public.campaign_plan_versions_guard() TO service_role;
GRANT ALL ON FUNCTION public.campaign_plan_objects_guard() TO service_role;
GRANT ALL ON FUNCTION public.enforce_campaign_plan_change_request(p_new public.change_requests, p_old public.change_requests, p_op text) TO service_role;
GRANT ALL ON FUNCTION public.create_campaign_plan_version(p_plan_id uuid, p_ad_account_id uuid, p_owner_user_id uuid, p_title text, p_brief jsonb, p_version jsonb) TO service_role;
GRANT ALL ON FUNCTION public.create_campaign_plan_change_request(p_plan_version_id uuid, p_owner_user_id uuid, p_request jsonb) TO service_role;


--
-- Security review L1: change_requests.status moves only along governed edges. executed, rejected and
-- expired are terminal; failed -> executed is the campaign-plan resume/retry path only, and a creation
-- never resumes while a rollback of it is pending or approved. Named to fire before the lineage trigger.
--

-- Meta's minor-unit offset per account currency, the same table as src/lib/platforms/meta/currency-offset.ts
-- (a parity test compares them). NULL: not a Meta ad-account currency.
CREATE FUNCTION public.meta_currency_offset(p_currency text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_currency IN ('CLP','COP','CRC','HUF','ISK','IDR','JPY','KRW','PYG','TWD','VND') THEN 1
    WHEN p_currency IN ('DZD','ARS','AUD','BHD','BDT','BOB','BGN','BRL','GBP','CAD','CNY','HRK','CZK','DKK',
                        'EGP','EUR','GTQ','HNL','HKD','INR','ILS','JOD','KES','LVL','LTL','MOP','MYR','MXN',
                        'NZD','NIO','NGN','NOK','PKR','PEN','PHP','PLN','QAR','RON','RUB','SAR','RSD','SGD',
                        'SKK','ZAR','SEK','CHF','THB','TRY','AED','UAH','USD','UYU','VEF','FBZ','VES') THEN 100
  END
$$;

REVOKE ALL ON FUNCTION public.meta_currency_offset(text) FROM PUBLIC;
GRANT ALL ON FUNCTION public.meta_currency_offset(text) TO service_role;

CREATE FUNCTION public.change_requests_status_transition_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  IF (OLD.status::text = 'pending' AND NEW.status::text IN ('approved', 'rejected', 'expired'))
     OR (OLD.status::text = 'approved' AND NEW.status::text IN ('executed', 'failed', 'rejected', 'expired')) THEN
    RETURN NEW;
  END IF;
  IF OLD.status::text = 'failed' AND NEW.status::text = 'executed' AND OLD.campaign_plan_version_id IS NOT NULL THEN
    IF OLD.action_type = 'create_campaign_paused' AND EXISTS (
         SELECT 1 FROM public.change_requests r
          WHERE r.rollback_of = OLD.id AND r.status::text IN ('pending', 'approved')) THEN
      RAISE EXCEPTION 'change_request_resume_blocked_by_pending_rollback';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'change_request_illegal_status_transition % -> %', OLD.status, NEW.status;
END;
$$;

COMMENT ON FUNCTION public.change_requests_status_transition_guard() IS 'Security review L1: pending -> approved|rejected|expired; approved -> executed|failed|rejected|expired; failed -> executed only for a campaign-plan request (resume or archive retry) with no pending or approved rollback of a creation. executed, rejected and expired are terminal.';

CREATE TRIGGER change_requests_status_transition_trg BEFORE UPDATE OF status ON public.change_requests FOR EACH ROW EXECUTE FUNCTION public.change_requests_status_transition_guard();

REVOKE ALL ON FUNCTION public.change_requests_status_transition_guard() FROM PUBLIC;
GRANT ALL ON FUNCTION public.change_requests_status_transition_guard() TO service_role;

--
-- PostgreSQL database dump complete
--

-- Final default privileges for objects created later (the browser roles still get nothing).
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON FUNCTIONS TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON FUNCTIONS TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES TO service_role;

-- Functions: Postgres grants EXECUTE to PUBLIC by default, and a per-schema default privilege cannot
-- remove that built-in grant (only a database-wide one can). Revoke it from every existing function
-- and from future ones, so the browser roles can execute nothing. Trigger functions keep working:
-- EXECUTE is checked when a trigger is created, not when it fires.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
